// II Samuel — tradução dos originais (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================


window.TEXTOS_SEED["2samuel"][1] = [
{s:"Davi sabe da morte de Saul"},
{v:1,t:"Depois da morte de Saul, Davi voltou da vitória sobre os amalecitas e ficou dois dias em Siceleg.",n:"O Segundo Livro de Samuel continua sem interrupção o primeiro: na Bíblia hebraica os dois formavam um só livro. É a história do reinado de Davi: a sua ascensão (capítulos 1 a 10), o seu pecado e as desgraças da sua casa (11 a 20), e alguns apêndices (21 a 24)."},
{v:2,t:"No terceiro dia, chegou do acampamento de Saul um homem com as vestes rasgadas e a cabeça coberta de terra. Ao chegar junto de Davi, lançou-se por terra e prostrou-se."},
{v:3,t:"Davi perguntou-lhe: De onde vens? Ele respondeu: Fugi do acampamento de Israel."},
{v:4,t:"Davi perguntou: Que aconteceu? Conta-me. Ele respondeu: O povo fugiu da batalha, e muitos do povo caíram mortos; e também Saul e seu filho Jônatas morreram."},
{v:5,t:"Davi perguntou ao jovem que lhe trazia a notícia: Como sabes que Saul e seu filho Jônatas estão mortos?",np:1},
{v:6,t:"O jovem que lhe dava a notícia respondeu: Por acaso eu estava no monte Gelboé, e Saul estava apoiado na sua lança, e os carros e os cavaleiros se aproximavam dele.",n:"Esta versão contradiz a de 1 Samuel 31, onde Saul se lança sobre a própria espada. O amalecita mente, ou exagera, esperando uma recompensa do novo rei."},
{v:7,t:"Voltando-se para trás, ele me viu e me chamou. Eu respondi: Aqui estou."},
{v:8,t:"Ele me perguntou: Quem és tu? Respondi: Sou um amalecita."},
{v:9,t:"Ele me disse: Põe-te sobre mim e mata-me, porque me tomou a agonia, e a vida ainda está toda em mim."},
{v:10,t:"Pus-me sobre ele e o matei, porque sabia que ele não sobreviveria à sua queda. Depois tomei o diadema que tinha na cabeça e o bracelete que tinha no braço, e os trouxe aqui ao meu senhor."},
{v:11,t:"Davi tomou as suas vestes e as rasgou, e o mesmo fizeram todos os homens que estavam com ele;",np:1},
{v:12,t:"e lamentaram-se, choraram e jejuaram até a tarde por Saul e por seu filho Jônatas, pelo povo do Senhor e pela casa de Israel, porque tinham caído pela espada."},
{v:13,t:"Davi perguntou ao jovem que lhe trouxera a notícia: De onde és? Ele respondeu: Sou filho de um estrangeiro, de um amalecita.",np:1,n:"Filho de um estrangeiro residente: vivia em Israel e estava sujeito às suas leis; não podia alegar ignorância."},
{v:14,t:"Davi lhe disse: Como não tiveste medo de estender a mão para matar o ungido do Senhor?"},
{v:15,t:"Davi chamou um dos seus rapazes e disse: Aproxima-te e mata-o! Ele o feriu, e ele morreu."},
{v:16,t:"E Davi lhe disse: O teu sangue caia sobre a tua cabeça, porque a tua própria boca te acusou, quando disseste: Eu matei o ungido do Senhor.",n:"Davi, que por duas vezes poupou Saul, não pode recompensar quem se gaba de o ter matado. E mostra a todo o Israel que não teve parte na morte do rei."},
{s:"O lamento de Davi por Saul e Jônatas"},
{v:17,t:"Davi entoou esta lamentação sobre Saul e sobre seu filho Jônatas,",np:1},
{v:18,t:"e mandou ensiná-la aos filhos de Judá: é o Cântico do Arco, que está escrito no livro do Justo. Ele disse:",n:"O Cântico do Arco, talvez por causa do arco de Jônatas (versículo 22). O livro do Justo era uma coleção de cânticos antigos, hoje perdida, citada também em Josué 10,13. A elegia é considerada obra autêntica de Davi: nela não se menciona Deus, apenas a dor humana."},
{v:19,l:["Os teus nobres, ó Israel, jazem mortos sobre os teus montes!","Como caíram os heróis!"]},
{v:20,l:["Não o anuncieis em Gat,","não o publiqueis nas ruas de Ascalon,","para que não se alegrem as filhas dos filisteus,","para que não exultem as filhas dos incircuncisos."],n:"As mulheres dos vencedores saíam a cantar a vitória, como as de Israel depois da morte de Golias (1 Samuel 18,6-7)."},
{v:21,l:["Montes de Gelboé, não caia sobre vós orvalho nem chuva,","nem haja em vós campos de primícias!","Porque ali foi aviltado o escudo dos heróis,","o escudo de Saul, como se não fosse ungido com óleo."],n:"Os escudos de couro eram untados com óleo antes do combate. A imagem sugere também a unção do rei, agora profanada."},
{v:22,l:["Do sangue dos feridos, da gordura dos heróis,","o arco de Jônatas nunca recuou,","e a espada de Saul não voltava vazia."]},
{v:23,l:["Saul e Jônatas, amáveis e encantadores na vida,","nem na morte se separaram;","eram mais velozes que as águias,","mais fortes que os leões."],n:"Nem na morte se separaram: apesar do conflito entre pai e filho por causa de Davi, Jônatas morreu ao lado de Saul."},
{v:24,l:["Filhas de Israel, chorai por Saul,","que vos vestia de escarlate e de delícias,","que punha enfeites de ouro nos vossos vestidos."]},
{v:25,l:["Como caíram os heróis no meio da batalha!","Jônatas jaz morto sobre os teus montes."]},
{v:26,l:["Estou em angústia por ti, meu irmão Jônatas;","tu me eras tão querido!","A tua amizade me era mais preciosa","do que o amor das mulheres."],n:"O amor de Jônatas não buscava nada para si: renunciou ao trono por Davi. É o que Davi celebra acima de todo outro afeto."},
{v:27,l:["Como caíram os heróis,","e pereceram as armas de guerra!"]}
];

window.TEXTOS_SEED["2samuel"][2] = [
{s:"Davi rei de Judá em Hebron"},
{v:1,t:"Depois disso, Davi consultou o Senhor, dizendo: Devo subir a alguma das cidades de Judá? O Senhor lhe respondeu: Sobe. Davi perguntou: Para onde subirei? Ele respondeu: Para Hebron.",n:"Hebron, a antiga cidade de Abraão, era o centro da tribo de Judá."},
{v:2,t:"Davi subiu para lá com as suas duas mulheres, Aquinoam de Jezrael e Abigail de Carmel, mulher de Nabal."},
{v:3,t:"Davi fez subir também os homens que estavam com ele, cada um com a sua família, e estabeleceram-se nas cidades dos arredores de Hebron."},
{v:4,t:"Vieram os homens de Judá e ali ungiram Davi rei sobre a casa de Judá. Contaram a Davi que os homens de Jabes de Galaad tinham sepultado Saul,",n:"Davi é ungido pela segunda vez, agora publicamente, pelos homens da sua tribo. Será ungido uma terceira vez por todo o Israel (5,3)."},
{v:5,t:"e Davi enviou mensageiros aos homens de Jabes de Galaad, para lhes dizer: Benditos sejais do Senhor, porque tivestes esta piedade para com Saul, vosso senhor, e o sepultastes.",np:1},
{v:6,t:"Agora, pois, que o Senhor use convosco de bondade e fidelidade; e também eu vos farei bem, porque fizestes isso."},
{v:7,t:"E agora, tende coragem e sede valentes; porque Saul, vosso senhor, morreu, mas a casa de Judá me ungiu seu rei.",n:"Ao agradecer, Davi convida discretamente Jabes a reconhecê-lo como sucessor de Saul."},
{s:"Isbaal rei de Israel"},
{v:8,t:"Abner, filho de Ner, chefe do exército de Saul, tomou Isbaal, filho de Saul, levou-o para Maanaim",np:1,n:"Isbaal quer dizer homem do senhor; baal, senhor, era também o nome do deus cananeu. Por isso o texto hebraico o chama Isbosete, homem da vergonha, substituindo o nome do ídolo. A Nova Vulgata restitui o nome original. Maanaim ficava a leste do Jordão, fora do alcance dos filisteus, que dominavam então o oeste."},
{v:9,t:"e o constituiu rei sobre Galaad, sobre Aser, sobre Jezrael, sobre Efraim, sobre Benjamim e sobre todo o Israel."},
{v:10,t:"Isbaal, filho de Saul, tinha quarenta anos quando começou a reinar sobre Israel, e reinou dois anos. Só a casa de Judá seguia Davi."},
{v:11,t:"O tempo que Davi reinou em Hebron sobre a casa de Judá foi de sete anos e seis meses."},
{s:"A guerra entre as duas casas"},
{v:12,t:"Abner, filho de Ner, saiu de Maanaim com os servos de Isbaal, filho de Saul, em direção a Gabaon.",np:1},
{v:13,t:"Joab, filho de Sárvia, também saiu com os servos de Davi, e encontraram-se junto ao tanque de Gabaon. Pararam uns de um lado do tanque e os outros do outro lado."},
{v:14,t:"Abner disse a Joab: Que os jovens se levantem e lutem diante de nós. Joab respondeu: Que se levantem."},
{v:15,t:"Levantaram-se e avançaram em número igual: doze de Benjamim, por parte de Isbaal, filho de Saul, e doze dos servos de Davi."},
{v:16,t:"Cada um agarrou o adversário pela cabeça e cravou-lhe a espada no flanco, e caíram todos juntos. Por isso aquele lugar, que fica em Gabaon, foi chamado Campo dos Flancos.",n:"Assim a Nova Vulgata, lembrando as espadas cravadas nos flancos; o nome hebraico, Helcat-Hasurim, quer dizer talvez campo das lâminas. O duelo, que devia decidir a guerra, termina empatado e desencadeia a batalha."},
{v:17,t:"Travou-se naquele dia uma batalha muito dura, e Abner e os homens de Israel foram derrotados pelos servos de Davi."},
{v:18,t:"Estavam ali os três filhos de Sárvia: Joab, Abisai e Asael. Asael era ligeiro de pés como uma gazela do campo.",np:1},
{v:19,t:"Asael perseguiu Abner, sem se desviar para a direita nem para a esquerda na perseguição."},
{v:20,t:"Abner olhou para trás e perguntou: És tu Asael? Ele respondeu: Sou eu."},
{v:21,t:"Abner lhe disse: Desvia-te para a direita ou para a esquerda, agarra um dos jovens e toma para ti os seus despojos. Mas Asael não quis deixar de persegui-lo."},
{v:22,t:"Abner tornou a dizer a Asael: Afasta-te, deixa de me seguir; por que hei de ser obrigado a te abater? Como poderia eu olhar de frente para Joab, teu irmão?"},
{v:23,t:"Mas ele não quis desviar-se. Então Abner o feriu no ventre com a ponta traseira da lança, e a lança saiu-lhe pelas costas; e ele caiu e morreu ali mesmo. Todos os que passavam pelo lugar onde Asael tinha caído morto se detinham.",n:"Abner mata o jovem contra a vontade, e sabe que abriu uma dívida de sangue com Joab. Ela será cobrada (3,27)."},
{v:24,t:"Joab e Abisai perseguiram Abner. Ao pôr do sol chegaram à colina de Ama, que fica defronte de Gia, no caminho do deserto de Gabaon.",np:1},
{v:25,t:"Os filhos de Benjamim reuniram-se atrás de Abner, formaram um só grupo e pararam no alto de uma colina."},
{v:26,t:"Abner gritou a Joab: Há de a espada devorar sem fim? Não sabes que o desespero é perigoso? Até quando esperarás para mandar o povo deixar de perseguir os seus irmãos?"},
{v:27,t:"Joab respondeu: Pela vida de Deus, se não tivesses falado, o povo só teria deixado de perseguir cada um o seu irmão pela manhã."},
{v:28,t:"Joab tocou a trombeta, e todo o exército parou; deixaram de perseguir Israel e não combateram mais."},
{v:29,t:"Abner e os seus homens caminharam toda aquela noite pela Arabá, atravessaram o Jordão, percorreram todo o desfiladeiro de Betron e chegaram a Maanaim.",np:1},
{v:30,t:"Joab voltou da perseguição a Abner e reuniu todo o povo: faltavam dos servos de Davi dezenove homens, além de Asael."},
{v:31,t:"Mas os servos de Davi tinham matado trezentos e sessenta homens de Benjamim e dos homens de Abner."},
{v:32,t:"Levaram Asael e o sepultaram no túmulo de seu pai, em Belém. Joab e os seus homens caminharam toda a noite e chegaram a Hebron ao romper do dia."}
];

window.TEXTOS_SEED["2samuel"][3] = [
{s:"Os filhos de Davi nascidos em Hebron"},
{v:1,t:"A guerra entre a casa de Saul e a casa de Davi foi longa: Davi ia-se fortalecendo cada vez mais, e a casa de Saul ia-se enfraquecendo dia após dia."},
{v:2,t:"Nasceram filhos a Davi em Hebron. O primogênito foi Amnon, de Aquinoam de Jezrael;",np:1},
{v:3,t:"o segundo, Queleab, de Abigail de Carmel, mulher de Nabal; o terceiro, Absalão, filho de Maaca, filha de Tolmai, rei de Gessur;",n:"O casamento com a filha do rei de Gessur, pequeno reino arameu a nordeste, era uma aliança política. Absalão se refugiará junto do avô (13,37)."},
{v:4,t:"o quarto, Adonias, filho de Hagit; o quinto, Safatias, filho de Abital;"},
{v:5,t:"o sexto, Jetraam, de Egla, mulher de Davi. Estes nasceram a Davi em Hebron.",n:"Amnon, Absalão e Adonias disputarão a sucessão, e as suas histórias encherão de sangue a casa de Davi."},
{s:"Abner passa para o lado de Davi"},
{v:6,t:"Durante a guerra entre a casa de Saul e a casa de Davi, Abner, filho de Ner, dominava a casa de Saul.",np:1},
{v:7,t:"Saul tinha tido uma concubina chamada Resfa, filha de Aiá. Isbaal disse a Abner:",n:"Tomar a concubina do rei morto era reivindicar a sua herança, isto é, o trono. Absalão fará o mesmo com as concubinas de Davi (16,22)."},
{v:8,t:"Por que te uniste à concubina de meu pai? Abner irritou-se muito com as palavras de Isbaal e disse: Sou eu uma cabeça de cão, de Judá? Até hoje tenho sido leal à casa de Saul, teu pai, a seus irmãos e a seus amigos, e não te entreguei nas mãos de Davi; e hoje me pedes contas por causa de uma mulher?"},
{v:9,t:"Que Deus faça isto a Abner e mais aquilo, se eu não fizer por Davi o que o Senhor lhe jurou:"},
{v:10,t:"transferir o reino da casa de Saul e firmar o trono de Davi sobre Israel e sobre Judá, desde Dã até Bersabeia."},
{v:11,t:"E Isbaal não pôde responder-lhe palavra, porque tinha medo dele."},
{v:12,t:"Abner enviou mensageiros a Davi, para lhe dizerem em seu nome: De quem é a terra? E também: Faze aliança comigo, e a minha mão estará contigo para trazer a ti todo o Israel.",np:1},
{v:13,t:"Davi respondeu: Muito bem; farei aliança contigo, mas exijo de ti uma coisa: não verás o meu rosto se primeiro não me trouxeres Micol, filha de Saul; então virás ver-me.",n:"Micol, filha de Saul, dava a Davi um título legítimo à sucessão da casa real."},
{v:14,t:"E Davi enviou mensageiros a Isbaal, filho de Saul, para lhe dizer: Devolve-me a minha mulher Micol, que desposei pelo preço de cem prepúcios de filisteus."},
{v:15,t:"Isbaal mandou tirá-la do marido, Faltiel, filho de Lais.",n:"Faltiel é o Falti de 1 Samuel 25,44."},
{v:16,t:"O marido a acompanhou, chorando, até Baurim. Então Abner lhe disse: Vai, volta para casa. E ele voltou.",n:"Um dos quadros mais tristes do livro: o homem que a amava segue-a chorando, e Micol torna-se moeda de troca entre os poderosos."},
{v:17,t:"Abner falou com os anciãos de Israel, dizendo: Há muito tempo desejais ter Davi como vosso rei.",np:1},
{v:18,t:"Agora, pois, fazei-o, porque o Senhor falou a Davi, dizendo: Pela mão de Davi, meu servo, salvarei o meu povo Israel da mão dos filisteus e da mão de todos os seus inimigos."},
{v:19,t:"Abner falou também aos benjaminitas; e foi a Hebron dizer a Davi tudo o que parecia bem a Israel e a toda a casa de Benjamim."},
{v:20,t:"Abner chegou a Hebron, junto de Davi, com vinte homens, e Davi ofereceu um banquete a Abner e aos homens que o acompanhavam."},
{v:21,t:"Abner disse a Davi: Vou partir para reunir todo o Israel em torno do rei, meu senhor; eles farão aliança contigo, e reinarás sobre tudo o que desejares. Davi despediu Abner, e ele partiu em paz."},
{s:"Joab assassina Abner"},
{v:22,t:"Nisso, os servos de Davi e Joab voltavam de uma incursão, trazendo grande despojo. Abner já não estava com Davi em Hebron, porque Davi o tinha despedido, e ele tinha partido em paz.",np:1},
{v:23,t:"Quando chegou Joab com todo o exército que estava com ele, contaram-lhe: Abner, filho de Ner, veio ao rei, e o rei o despediu, e ele partiu em paz."},
{v:24,t:"Joab foi ter com o rei e disse: Que fizeste? Abner veio a ti; por que o deixaste ir, e ele se foi embora?"},
{v:25,t:"Não conheces Abner, filho de Ner? Veio para te enganar, para conhecer as tuas entradas e saídas e saber tudo o que fazes."},
{v:26,t:"Joab saiu da presença de Davi e enviou mensageiros atrás de Abner, que o fizeram voltar da cisterna de Sira, sem que Davi o soubesse."},
{v:27,t:"Quando Abner voltou a Hebron, Joab levou-o à parte, para dentro da porta, como para lhe falar em particular, e ali o feriu no ventre; e ele morreu, em vingança do sangue de Asael, irmão de Joab.",n:"Joab vinga o irmão, mas elimina também um rival: Abner seria o chefe do exército do reino unido. Hebron era cidade de refúgio, onde a vingança do sangue era proibida (Josué 20,7)."},
{v:28,t:"Quando Davi soube do fato, disse: Eu e o meu reino somos para sempre inocentes, diante do Senhor, do sangue de Abner, filho de Ner.",np:1},
{v:29,t:"Que ele recaia sobre a cabeça de Joab e sobre toda a casa de seu pai! Que nunca falte na casa de Joab quem sofra de fluxo, ou de lepra, ou quem maneje o fuso, ou quem caia pela espada, ou quem careça de pão!",n:"Quem maneje o fuso: um homem incapaz para a guerra, reduzido aos trabalhos das mulheres; ou, segundo outros, quem ande de muletas."},
{v:30,t:"Joab e seu irmão Abisai mataram Abner porque ele tinha matado Asael, irmão deles, em Gabaon, na batalha."},
{v:31,t:"Davi disse a Joab e a todo o povo que estava com ele: Rasgai as vossas vestes, cingi-vos de pano de saco e fazei luto diante do corpo de Abner. E o rei Davi seguia o féretro.",np:1},
{v:32,t:"Sepultaram Abner em Hebron. O rei levantou a voz e chorou sobre o túmulo de Abner, e todo o povo também chorou."},
{v:33,l:["E o rei entoou esta lamentação sobre Abner:","Devia Abner morrer","como morre o insensato?"],n:"Insensato: em hebraico nabal, o nome do homem de 1 Samuel 25. Abner, o grande guerreiro, morreu como um tolo, numa emboscada."},
{v:34,l:["As tuas mãos não estavam atadas,","nem os teus pés presos em grilhões;","caíste como se cai diante dos malfeitores.","E todo o povo redobrou o pranto por ele."]},
{v:35,t:"Depois todo o povo veio insistir com Davi para que comesse alguma coisa enquanto ainda era dia; mas Davi jurou, dizendo: Que Deus me faça isto e mais aquilo, se eu provar pão ou qualquer outra coisa antes do pôr do sol!",np:1},
{v:36,t:"Todo o povo o soube, e isso lhe agradou, como agradava a todo o povo tudo o que o rei fazia."},
{v:37,t:"Naquele dia, todo o povo e todo o Israel reconheceram que não tinha sido por ordem do rei que Abner, filho de Ner, fora morto."},
{v:38,t:"E o rei disse aos seus servos: Não sabeis que hoje caiu em Israel um chefe, um grande homem?"},
{v:39,t:"Eu ainda sou fraco, embora ungido rei; e esses homens, os filhos de Sárvia, são mais duros do que eu. Que o Senhor retribua ao malfeitor segundo a sua maldade.",n:"Davi não pode punir Joab, de quem depende; deixa a vingança a Deus. Só no leito de morte pedirá a Salomão que faça justiça (1 Reis 2,5-6)."}
];

window.TEXTOS_SEED["2samuel"][4] = [
{s:"O assassinato de Isbaal"},
{v:1,t:"Quando Isbaal, filho de Saul, soube que Abner tinha morrido em Hebron, desfaleceu-lhe a coragem, e todo o Israel ficou consternado."},
{v:2,t:"O filho de Saul tinha dois chefes de bando: um chamava-se Baana, e o outro, Recab; eram filhos de Remon, de Berot, da tribo de Benjamim, pois também Berot era considerada parte de Benjamim.",np:1},
{v:3,t:"Os habitantes de Berot tinham fugido para Getaim, onde vivem como estrangeiros até hoje."},
{v:4,t:"Jônatas, filho de Saul, tinha um filho aleijado dos pés. Tinha cinco anos quando chegou de Jezrael a notícia da morte de Saul e de Jônatas; a sua ama o tomou e fugiu, mas, na pressa da fuga, o menino caiu e ficou coxo. Chamava-se Meribaal.",n:"A nota prepara o capítulo 9: Meribaal é o último descendente de Saul capaz de reivindicar o trono, mas a sua deficiência o afasta. O hebraico chama-o Mefiboset, trocando baal por boset, vergonha, como no nome de Isbaal; a Nova Vulgata restitui o nome original."},
{v:5,t:"Os filhos de Remon, de Berot, Recab e Baana, partiram e chegaram, no maior calor do dia, à casa de Isbaal, que dormia a sesta na sua cama; a porteira da casa, que limpava trigo, tinha adormecido.",np:1,n:"A porteira adormecida vem da versão grega, que a Nova Vulgata segue; o hebraico diz que os assassinos entraram como quem vai buscar trigo."},
{v:6,t:"Entraram até o interior da casa, e Recab e seu irmão Baana o feriram no ventre e fugiram."},
{v:7,t:"Entraram na casa quando ele dormia na cama, no seu quarto; feriram-no, mataram-no e cortaram-lhe a cabeça. Depois, levando a cabeça, caminharam a noite inteira pelo caminho da Arabá."},
{v:8,t:"Levaram a cabeça de Isbaal a Davi, em Hebron, e disseram ao rei: Aqui está a cabeça de Isbaal, filho de Saul, teu inimigo, que procurava tirar-te a vida. Hoje o Senhor concedeu ao rei, meu senhor, vingança de Saul e da sua descendência."},
{v:9,t:"Davi respondeu a Recab e a seu irmão Baana, filhos de Remon, de Berot: Pela vida do Senhor, que me livrou de toda angústia:",np:1},
{v:10,t:"aquele que me trouxe a notícia de que Saul estava morto, julgando trazer uma boa notícia, eu o prendi e o matei em Siceleg; foi essa a recompensa que lhe dei pela notícia."},
{v:11,t:"Quanto mais agora, quando homens perversos mataram um homem inocente em sua casa, na sua cama! Não hei de pedir-vos contas do seu sangue e eliminar-vos da terra?",n:"Mais uma vez, Davi recusa subir ao trono pelo crime alheio e mostra a todo o Israel que não quis a morte do filho de Saul."},
{v:12,t:"Davi deu ordem aos seus rapazes, e eles os mataram; cortaram-lhes as mãos e os pés e os penduraram junto ao tanque de Hebron. A cabeça de Isbaal, tomaram-na e a sepultaram no túmulo de Abner, em Hebron."}
];

window.TEXTOS_SEED["2samuel"][5] = [
{s:"Davi rei de todo o Israel"},
{v:1,t:"Todas as tribos de Israel vieram ter com Davi em Hebron e disseram: Somos teus ossos e tua carne.",n:"A mesma expressão que Adão diz de Eva: somos da mesma família. As tribos do Norte reconhecem o parentesco com o rei de Judá."},
{v:2,t:"Já antes, quando Saul era nosso rei, eras tu que conduzias Israel nas suas saídas e entradas. E o Senhor te disse: Tu apascentarás o meu povo Israel e serás o chefe de Israel.",n:"O rei como pastor: a imagem, comum no Oriente, recebe na Bíblia um sentido novo. Os profetas a retomarão para anunciar o Messias, filho de Davi, e Jesus se dirá o bom pastor."},
{v:3,t:"Todos os anciãos de Israel vieram ter com o rei em Hebron; o rei Davi fez aliança com eles em Hebron, diante do Senhor, e eles ungiram Davi rei sobre Israel.",n:"Terceira unção de Davi: depois da de Samuel, na intimidade da família (1 Samuel 16), e da de Judá (2,4). A aliança com os anciãos define os deveres do rei para com o povo."},
{v:4,t:"Davi tinha trinta anos quando começou a reinar, e reinou quarenta anos:",np:1},
{v:5,t:"em Hebron reinou sobre Judá sete anos e seis meses, e em Jerusalém reinou trinta e três anos sobre todo o Israel e Judá."},
{s:"A conquista de Jerusalém"},
{v:6,t:"O rei marchou com os seus homens sobre Jerusalém, contra os jebuseus que habitavam a região. Estes disseram a Davi: Não entrarás aqui; até os cegos e os coxos te repelirão! Queriam dizer: Davi não entrará aqui.",np:1,n:"Jerusalém, cidade cananeia que nenhuma tribo tinha conquistado, ficava entre Judá e Benjamim. Tomada por Davi com os seus homens, tornou-se a capital neutra do reino, pertencente ao rei e não a uma tribo. Os jebuseus confiavam tanto nas suas muralhas que diziam bastarem cegos e coxos para defendê-las."},
{v:7,t:"Mas Davi tomou a fortaleza de Sião, que é a Cidade de Davi."},
{v:8,t:"Naquele dia Davi dissera: Quem quiser ferir os jebuseus, suba pelo canal da fonte, até esses coxos e cegos que Davi detesta. Por isso se diz: Cego e coxo não entrarão na casa.",n:"O canal da fonte: talvez o poço que levava da cidade à fonte de Gion, pelo qual os homens de Davi teriam entrado. O provérbio foi depois aplicado ao templo, onde os cegos e os coxos não entravam; Jesus curará cegos e coxos no templo (Mateus 21,14)."},
{v:9,t:"Davi estabeleceu-se na fortaleza e chamou-a Cidade de Davi; e construiu ao redor, desde o Milo para dentro.",n:"O Milo, palavra que quer dizer aterro, era talvez um sistema de terraços que sustentava as construções na encosta da colina."},
{v:10,t:"Davi ia crescendo em poder, e o Senhor, Deus dos exércitos, estava com ele."},
{v:11,t:"Hiram, rei de Tiro, enviou mensageiros a Davi, com madeira de cedro, carpinteiros e pedreiros, que construíram uma casa para Davi.",np:1,n:"Hiram será também o aliado de Salomão na construção do templo. Tiro, na costa fenícia, era famosa pelos seus artesãos e pelo comércio marítimo."},
{v:12,t:"E Davi reconheceu que o Senhor o tinha confirmado rei sobre Israel e tinha exaltado o seu reino por amor do seu povo Israel."},
{v:13,t:"Depois de vir de Hebron, Davi tomou ainda concubinas e mulheres de Jerusalém, e nasceram-lhe outros filhos e filhas.",np:1},
{v:14,t:"Estes são os nomes dos que lhe nasceram em Jerusalém: Samua, Sobab, Natã, Salomão,",n:"Natã é, segundo Lucas 3,31, o antepassado de Jesus; Salomão, segundo Mateus 1,6."},
{v:15,t:"Jebaar, Elisua, Nefeg,"},
{v:16,t:"Jafia, Elisama, Eliada e Elifalet."},
{s:"Vitórias sobre os filisteus"},
{v:17,t:"Quando os filisteus souberam que Davi tinha sido ungido rei sobre Israel, subiram todos à sua procura. Davi soube disso e desceu à fortaleza.",np:1,n:"Enquanto Davi era rei só de Judá, os filisteus o consideravam vassalo; rei de todo o Israel, tornava-se um perigo."},
{v:18,t:"Os filisteus chegaram e espalharam-se pelo vale dos Refaim."},
{v:19,t:"Davi consultou o Senhor: Devo subir contra os filisteus? Tu os entregarás nas minhas mãos? O Senhor respondeu a Davi: Sobe, porque certamente entregarei os filisteus nas tuas mãos."},
{v:20,t:"Davi foi a Baal-Farasim, isto é, Senhor das Brechas, e ali os derrotou, e disse: O Senhor abriu brecha entre os meus inimigos diante de mim, como as águas abrem brecha. Por isso deram àquele lugar o nome de Baal-Farasim.",n:"Isaías lembrará esta vitória: o Senhor se levantará como no monte Farasim (Isaías 28,21)."},
{v:21,t:"Os filisteus deixaram ali os seus ídolos, e Davi e os seus homens os levaram.",n:"Assim os filisteus perdem os seus deuses, como Israel perdera a arca (1 Samuel 4). As Crônicas acrescentam que Davi mandou queimá-los (1 Crônicas 14,12)."},
{v:22,t:"Os filisteus tornaram a subir e espalharam-se pelo vale dos Refaim.",np:1},
{v:23,t:"Davi consultou o Senhor, que lhe respondeu: Não subas; dá a volta por trás deles e ataca-os pelo lado das balsameiras.",n:"Balsameiras: árvores de identificação incerta."},
{v:24,t:"Quando ouvires um ruído de passos na copa das balsameiras, então lança-te ao combate, porque o Senhor terá saído à tua frente para ferir o exército dos filisteus.",n:"O ruído de passos nas copas das árvores é o sinal do Senhor que marcha à frente do seu exército."},
{v:25,t:"Davi fez como o Senhor lhe ordenara e bateu os filisteus desde Gabaon até a entrada de Gazer.",n:"Gabaon: assim a versão grega, como em 1 Crônicas 14,16; o hebraico diz Gaba."}
];

window.TEXTOS_SEED["2samuel"][6] = [
{s:"A arca levada para Jerusalém"},
{v:1,t:"Davi reuniu de novo todos os homens escolhidos de Israel, trinta mil."},
{v:2,t:"Levantou-se e partiu, com todo o povo que estava com ele, para Baala de Judá, a fim de trazer de lá a arca de Deus, sobre a qual é invocado o nome do Senhor dos exércitos, que está sentado sobre os querubins.",n:"Baala de Judá é Cariat-Iarim, onde a arca estava desde a sua volta da terra dos filisteus (1 Samuel 7,1). Levando-a para Jerusalém, Davi faz da sua capital política também o centro religioso de todo o Israel."},
{v:3,t:"Puseram a arca de Deus num carro novo e a tiraram da casa de Abinadab, que ficava na colina. Oza e Aio, filhos de Abinadab, conduziam o carro:"},
{v:4,t:"Oza caminhava ao lado da arca, e Aio ia à frente dela."},
{v:5,t:"Davi e todo o Israel dançavam diante do Senhor com todas as forças, com cânticos, cítaras, harpas, tamborins, sistros e címbalos.",n:"Com todas as forças e com cânticos: assim a Nova Vulgata, com 1 Crônicas 13,8; o hebraico diz com toda sorte de instrumentos de cipreste."},
{v:6,t:"Quando chegaram à eira de Nacon, Oza estendeu a mão para a arca de Deus e a segurou, porque os bois a tinham feito balançar.",np:1},
{v:7,t:"A ira do Senhor inflamou-se contra Oza, e Deus o feriu ali por aquela temeridade; e ele morreu ali, junto da arca de Deus.",n:"A arca devia ser levada nos ombros pelos levitas, e ninguém podia tocá-la (Números 4,15). O carro era o modo dos filisteus. A morte de Oza escandaliza o leitor, como escandalizou Davi; a narrativa quer mostrar que a santidade de Deus não se deixa manejar."},
{v:8,t:"Davi ficou aborrecido porque o Senhor tinha aberto uma brecha em Oza; e aquele lugar se chama até hoje Farés-Oza, isto é, Brecha de Oza."},
{v:9,t:"Naquele dia Davi teve medo do Senhor e disse: Como poderá a arca do Senhor vir para junto de mim?"},
{v:10,t:"E Davi não quis levar a arca do Senhor para junto de si, na Cidade de Davi, mas a fez levar para a casa de Obed-Edom, de Gat.",n:"Obed-Edom, de Gat: um filisteu, talvez da guarda estrangeira de Davi, a quem se confia a arca perigosa."},
{v:11,t:"A arca do Senhor ficou três meses na casa de Obed-Edom, de Gat, e o Senhor abençoou Obed-Edom e toda a sua casa."},
{v:12,t:"Contaram ao rei Davi: O Senhor abençoou Obed-Edom e tudo o que ele tem, por causa da arca de Deus. Então Davi foi e fez subir com alegria a arca de Deus da casa de Obed-Edom para a Cidade de Davi.",np:1},
{v:13,t:"Quando os que levavam a arca do Senhor tinham dado seis passos, ele sacrificou um boi e um bezerro cevado.",n:"Agora a arca é levada nos ombros, como a Lei mandava."},
{v:14,t:"E Davi dançava com todas as forças diante do Senhor; Davi estava cingido com um efod de linho.",n:"O efod de linho era uma veste sacerdotal curta, como a que Samuel usava menino (1 Samuel 2,18). Davi age aqui como rei e sacerdote."},
{v:15,t:"Assim Davi e toda a casa de Israel fizeram subir a arca do Senhor entre aclamações e ao som da trombeta."},
{v:16,t:"Quando a arca do Senhor entrou na Cidade de Davi, Micol, filha de Saul, olhando pela janela, viu o rei Davi pulando e dançando diante do Senhor, e desprezou-o no seu coração.",np:1},
{v:17,t:"Introduziram a arca do Senhor e a colocaram no seu lugar, no meio da tenda que Davi tinha armado para ela; e Davi ofereceu diante do Senhor holocaustos e sacrifícios de comunhão."},
{v:18,t:"Quando acabou de oferecer os holocaustos e os sacrifícios de comunhão, Davi abençoou o povo em nome do Senhor dos exércitos."},
{v:19,t:"E distribuiu a toda a multidão de Israel, homens e mulheres, a cada um, um pão redondo, um bolo de tâmaras e um bolo de passas. Depois todo o povo voltou, cada um para a sua casa."},
{s:"Davi e Micol"},
{v:20,t:"Davi voltou para abençoar a sua casa, e Micol, filha de Saul, saiu ao encontro de Davi e disse: Que glória para o rei de Israel, hoje, descobrir-se diante das servas dos seus servos, como se descobre um bufão qualquer!",np:1},
{v:21,t:"Davi respondeu a Micol: É diante do Senhor que eu danço. Bendito seja o Senhor, que me escolheu de preferência a teu pai e a toda a sua casa, para me constituir chefe do povo do Senhor, de Israel!"},
{v:22,t:"Dançarei diante do Senhor e me farei ainda mais desprezível do que isto, e serei humilde aos meus próprios olhos; mas as servas de quem falaste, diante delas serei honrado.",n:"Davi não se envergonha de se rebaixar diante de Deus: a verdadeira grandeza do rei é a humildade diante do Senhor."},
{v:23,t:"E Micol, filha de Saul, não teve filhos até o dia da sua morte.",n:"A esterilidade de Micol encerra a descendência de Saul no trono: nenhum neto de Saul reinará."}
];

window.TEXTOS_SEED["2samuel"][7] = [
{s:"A profecia de Natã"},
{v:1,t:"Quando o rei já habitava em sua casa, e o Senhor lhe tinha dado descanso de todos os inimigos ao redor,"},
{v:2,t:"disse ao profeta Natã: Vê: eu moro numa casa de cedro, e a arca de Deus está no meio de cortinas!",n:"Natã, profeta da corte, aparece aqui pela primeira vez; será ele quem repreenderá Davi pelo seu pecado (capítulo 12)."},
{v:3,t:"Natã respondeu ao rei: Faze tudo o que tens no coração, porque o Senhor está contigo."},
{v:4,t:"Mas naquela mesma noite a palavra do Senhor foi dirigida a Natã nestes termos:",np:1},
{v:5,t:"Vai e dize ao meu servo Davi: Assim diz o Senhor: És tu que me construirás uma casa para eu habitar?",n:"O capítulo joga com a palavra casa: Davi quer construir uma casa, isto é, um templo, para Deus; é Deus quem construirá uma casa, isto é, uma dinastia, para Davi."},
{v:6,t:"Desde o dia em que tirei os filhos de Israel do Egito até hoje, nunca habitei numa casa; andei de um lugar para outro numa tenda e num tabernáculo."},
{v:7,t:"Em todos os lugares por onde andei com todos os filhos de Israel, acaso disse alguma vez a algum dos juízes de Israel, a quem ordenei que apascentasse o meu povo Israel: Por que não me construístes uma casa de cedro?"},
{v:8,t:"Agora, pois, assim dirás ao meu servo Davi: Assim diz o Senhor dos exércitos: Eu te tirei das pastagens, de detrás das ovelhas, para que fosses chefe do meu povo Israel.",np:1},
{v:9,t:"Estive contigo por onde quer que andaste e exterminei diante de ti todos os teus inimigos; e te farei um nome grande como o nome dos grandes da terra."},
{v:10,t:"Prepararei um lugar para o meu povo Israel e o plantarei, e ele habitará no seu lugar e não será mais perturbado; e os perversos não tornarão a oprimi-lo como antes,"},
{v:11,t:"desde o dia em que constituí juízes sobre o meu povo Israel; e te darei descanso de todos os teus inimigos. E o Senhor te anuncia que o Senhor te fará uma casa."},
{v:12,t:"Quando se completarem os teus dias e repousares com teus pais, suscitarei depois de ti a tua descendência, que sairá das tuas entranhas, e firmarei o seu reino.",n:"É a promessa messiânica fundamental do Antigo Testamento. Aplica-se primeiro a Salomão, que construirá o templo; mas o reino para sempre ultrapassa Salomão e a dinastia histórica. Os profetas e os Salmos (Salmo 89; 132) esperarão o filho de Davi, e o Novo Testamento o reconhecerá em Jesus (Lucas 1,32-33)."},
{v:13,t:"Ele construirá uma casa ao meu nome, e eu firmarei para sempre o trono do seu reino."},
{v:14,t:"Eu serei para ele um pai, e ele será para mim um filho. Se ele cometer alguma falta, eu o castigarei com vara de homens e com açoites humanos,",n:"Eu serei para ele um pai: o rei é filho adotivo de Deus. A Carta aos Hebreus aplica estas palavras a Cristo, o Filho (Hebreus 1,5)."},
{v:15,t:"mas não retirarei dele a minha misericórdia, como a retirei de Saul, a quem afastei de diante de ti."},
{v:16,t:"A tua casa e o teu reino serão estáveis para sempre diante de mim, e o teu trono será firme para sempre."},
{v:17,t:"Natã falou a Davi segundo todas estas palavras e toda esta visão."},
{s:"A oração de Davi"},
{v:18,t:"Então o rei Davi entrou, sentou-se diante do Senhor e disse: Quem sou eu, Senhor Deus, e que é a minha casa, para que me tenhas trazido até aqui?",np:1,n:"Diante do Senhor: na tenda da arca."},
{v:19,t:"E ainda isso te pareceu pouco, Senhor Deus: falaste também da casa do teu servo para um futuro distante. Esta é a lei para os homens, Senhor Deus!",n:"A última frase é obscura. Talvez: é assim que tratas um homem? ou: esta é a promessa dada à humanidade."},
{v:20,t:"Que mais poderia Davi dizer-te? Tu conheces o teu servo, Senhor Deus."},
{v:21,t:"Por causa da tua palavra e segundo o teu coração, fizeste todas estas grandes coisas, para dá-las a conhecer ao teu servo."},
{v:22,t:"Por isso és grande, Senhor Deus: não há ninguém como tu, e não há Deus fora de ti, segundo tudo o que ouvimos com os nossos ouvidos."},
{v:23,t:"E que outra nação há na terra como o teu povo Israel, que Deus foi resgatar para fazer dele o seu povo, para dar-lhe um nome e fazer por ele coisas grandes e terríveis, expulsando diante do teu povo, que resgataste do Egito, as nações e os seus deuses?"},
{v:24,t:"Tu firmaste para ti o teu povo Israel, para que fosse o teu povo para sempre; e tu, Senhor, te tornaste o seu Deus."},
{v:25,t:"Agora, pois, Senhor Deus, confirma para sempre a palavra que disseste sobre o teu servo e sobre a sua casa, e faze como disseste!",np:1},
{v:26,t:"Que o teu nome seja engrandecido para sempre, e que se diga: O Senhor dos exércitos é o Deus de Israel! E a casa do teu servo Davi será firme diante de ti,"},
{v:27,t:"porque tu, Senhor dos exércitos, Deus de Israel, fizeste esta revelação ao teu servo: Eu te construirei uma casa. Por isso o teu servo encontrou coragem para te dirigir esta oração."},
{v:28,t:"Agora, pois, Senhor Deus, tu és Deus, e as tuas palavras são verdade; e prometeste ao teu servo este bem."},
{v:29,t:"Digna-te, pois, abençoar a casa do teu servo, para que ela permaneça para sempre diante de ti; porque tu, Senhor Deus, falaste, e com a tua bênção a casa do teu servo será bendita para sempre."}
];

window.TEXTOS_SEED["2samuel"][8] = [
{s:"As vitórias de Davi"},
{v:1,t:"Depois disso, Davi derrotou os filisteus e os humilhou, e tomou das mãos dos filisteus Gat e as suas cidades.",n:"Gat e as suas cidades: assim a Nova Vulgata, com 1 Crônicas 18,1; o hebraico traz uma expressão obscura, Meteg-Ama, talvez a rédea da metrópole, isto é, a hegemonia."},
{v:2,t:"Derrotou também Moab e mediu os moabitas com um cordel, fazendo-os deitar no chão: media dois cordéis para os matar e um cordel inteiro para os deixar com vida. E Moab ficou sujeito a Davi, pagando-lhe tributo.",n:"Um terço dos prisioneiros foi poupado. O tratamento cruel contrasta com a amizade de outrora, quando Davi confiou os pais ao rei de Moab (1 Samuel 22,3-4); o texto não explica a mudança."},
{v:3,t:"Davi derrotou também Adadezer, filho de Roob, rei de Soba, quando este ia estabelecer o seu domínio sobre o rio Eufrates.",np:1,n:"Soba era um reino arameu ao norte de Damasco, o mais poderoso da Síria naquele tempo."},
{v:4,t:"Davi tomou-lhe mil e setecentos cavaleiros e vinte mil soldados de infantaria; e cortou os jarretes a todos os cavalos dos carros, deixando só os necessários para cem carros.",n:"Israel, povo da montanha, não sabia ainda usar os carros de guerra; e a Lei desconfiava dos cavalos, sinal do poder humano (Deuteronômio 17,16)."},
{v:5,t:"Os arameus de Damasco vieram em socorro de Adadezer, rei de Soba, e Davi matou vinte e dois mil homens dos arameus."},
{v:6,t:"E Davi estabeleceu guarnições na Síria de Damasco, e os arameus ficaram sujeitos a Davi, pagando-lhe tributo. O Senhor dava vitória a Davi por onde quer que ele fosse."},
{v:7,t:"Davi tomou as armas de ouro que os servos de Adadezer tinham e levou-as para Jerusalém;"},
{v:8,t:"e de Tebá e de Berotai, cidades de Adadezer, o rei Davi tomou grande quantidade de bronze.",n:"As Crônicas acrescentam que Salomão usou esse bronze para o mar de bronze, as colunas e os utensílios do templo (1 Crônicas 18,8)."},
{v:9,t:"Tou, rei de Emat, soube que Davi tinha derrotado todo o exército de Adadezer,",np:1},
{v:10,t:"e enviou seu filho Adoram ao rei Davi, para saudá-lo e felicitá-lo por ter combatido contra Adadezer e o ter derrotado; porque Adadezer estava em guerra com Tou. Adoram trouxe objetos de prata, de ouro e de bronze,"},
{v:11,t:"que o rei Davi também consagrou ao Senhor, junto com a prata e o ouro que tinha consagrado de todas as nações que submetera:"},
{v:12,t:"da Síria, de Moab, dos amonitas, dos filisteus, de Amalec, e do despojo de Adadezer, filho de Roob, rei de Soba."},
{v:13,t:"Davi ganhou fama quando voltou de derrotar Edom no vale do Sal: dezoito mil homens.",n:"Edom: assim a Nova Vulgata, com 1 Crônicas 18,12; o hebraico diz Aram, confusão fácil entre duas palavras quase iguais na escrita hebraica."},
{v:14,t:"Estabeleceu guarnições em Edom, e todo o Edom ficou sujeito a Davi. O Senhor dava vitória a Davi por onde quer que ele fosse.",n:"Davi constrói um pequeno império, do Egito ao Eufrates: a promessa feita a Abraão (Gênesis 15,18) parece cumprir-se."},
{s:"Os oficiais de Davi"},
{v:15,t:"Davi reinou sobre todo o Israel, e praticava o direito e a justiça para com todo o seu povo.",np:1},
{v:16,t:"Joab, filho de Sárvia, comandava o exército; Josafá, filho de Ailud, era o arauto;"},
{v:17,t:"Sadoc, filho de Aquitob, e Abiatar, filho de Aquimelec, eram sacerdotes; Saraías era o escriba;",n:"Abiatar, filho de Aquimelec: assim a Nova Vulgata; o hebraico inverte os nomes, por erro de copista. Sadoc aparece aqui pela primeira vez; os seus descendentes serão os sumos sacerdotes do templo de Jerusalém."},
{v:18,t:"Banaías, filho de Joiada, comandava os cereteus e os feleteus; e os filhos de Davi eram sacerdotes.",n:"Os cereteus e os feleteus, cretenses e filisteus, formavam a guarda estrangeira do rei, fiel só a ele. Sacerdotes: o título, dado aos filhos do rei, talvez designe uma função na corte; as Crônicas dizem os primeiros ao lado do rei (1 Crônicas 18,17)."}
];

window.TEXTOS_SEED["2samuel"][9] = [
{s:"Davi e Meribaal"},
{v:1,t:"Davi perguntou: Resta ainda alguém da casa de Saul, a quem eu possa fazer bem por amor de Jônatas?",n:"Davi cumpre a promessa feita a Jônatas (1 Samuel 20,14-15). Mas o gesto de bondade é também prudência: o neto de Saul ficará sob os olhos do rei."},
{v:2,t:"Havia um servo da casa de Saul chamado Siba. Chamaram-no à presença de Davi, e o rei lhe perguntou: És tu Siba? Ele respondeu: Sou eu, teu servo."},
{v:3,t:"O rei perguntou: Não resta mais ninguém da casa de Saul, a quem eu possa fazer a bondade de Deus? Siba respondeu ao rei: Resta ainda um filho de Jônatas, aleijado dos pés."},
{v:4,t:"Onde está ele? perguntou o rei. Siba respondeu ao rei: Está na casa de Maquir, filho de Amiel, em Lodabar."},
{v:5,t:"O rei Davi mandou buscá-lo na casa de Maquir, filho de Amiel, em Lodabar.",np:1},
{v:6,t:"Quando Meribaal, filho de Jônatas, filho de Saul, chegou junto de Davi, caiu com o rosto por terra e prostrou-se. Davi disse: Meribaal! Ele respondeu: Aqui está o teu servo."},
{v:7,t:"Davi lhe disse: Não tenhas medo, porque certamente usarei de bondade contigo por amor de Jônatas, teu pai; eu te restituirei todas as terras de Saul, teu pai, e tu comerás sempre à minha mesa.",n:"Não tenhas medo: o novo rei costumava exterminar a família do rei anterior. Meribaal espera o pior."},
{v:8,t:"Ele se prostrou e disse: Quem é o teu servo, para que te voltes para um cão morto como eu?"},
{v:9,t:"Então o rei chamou Siba, servo de Saul, e lhe disse: Tudo o que pertencia a Saul e a toda a sua casa, eu o dou ao filho do teu senhor.",np:1},
{v:10,t:"Tu, os teus filhos e os teus servos lavrareis a terra para ele e recolhereis os frutos, para que a casa do teu senhor tenha pão para comer; mas Meribaal, filho do teu senhor, comerá sempre à minha mesa. Siba tinha quinze filhos e vinte servos."},
{v:11,t:"Siba respondeu ao rei: O teu servo fará tudo o que o rei, meu senhor, ordenou ao seu servo. E Meribaal comia à mesa do rei como um dos filhos do rei."},
{v:12,t:"Meribaal tinha um filho pequeno, chamado Mica; e todos os que moravam na casa de Siba estavam a serviço de Meribaal."},
{v:13,t:"Meribaal morava em Jerusalém, porque comia sempre à mesa do rei; e era coxo dos dois pés."}
];

window.TEXTOS_SEED["2samuel"][10] = [
{s:"A afronta dos amonitas"},
{v:1,t:"Depois disso, morreu o rei dos amonitas, e seu filho Hanon reinou em seu lugar."},
{v:2,t:"Davi disse: Usarei de bondade com Hanon, filho de Naás, como seu pai usou de bondade comigo. E Davi enviou os seus servos para consolá-lo pela morte do pai. Quando os servos de Davi chegaram à terra dos amonitas,",n:"Naás, talvez o mesmo que Saul derrotou em Jabes (1 Samuel 11), tinha ajudado Davi, inimigo de Saul, no tempo da sua fuga."},
{v:3,t:"os chefes dos amonitas disseram a Hanon, seu senhor: Pensas que é para honrar teu pai que Davi te enviou consoladores? Não é antes para investigar e explorar a cidade, e destruí-la, que Davi te enviou os seus servos?"},
{v:4,t:"Hanon tomou os servos de Davi, rapou-lhes metade da barba, cortou-lhes as vestes pelo meio, até as nádegas, e despediu-os.",n:"Cortar a barba de um homem era a pior afronta; a barba era sinal de dignidade e de virilidade."},
{v:5,t:"Contaram isso a Davi, e ele mandou alguém ao encontro deles, porque estavam profundamente envergonhados; e o rei lhes mandou dizer: Ficai em Jericó até que a vossa barba cresça, e depois voltai."},
{s:"Guerra contra os amonitas e os arameus"},
{v:6,t:"Os amonitas, vendo que se tinham tornado odiosos a Davi, mandaram contratar os arameus de Bet-Roob e os arameus de Soba, vinte mil soldados de infantaria, o rei de Maaca, com mil homens, e os homens de Tob, doze mil.",np:1},
{v:7,t:"Quando Davi soube disso, enviou Joab com todo o exército dos valentes."},
{v:8,t:"Os amonitas saíram e dispuseram-se em linha de batalha diante da porta da cidade; os arameus de Soba e de Roob e os homens de Tob e de Maaca estavam à parte, no campo."},
{v:9,t:"Joab, vendo que tinha de enfrentar o combate pela frente e pela retaguarda, escolheu os melhores de Israel e dispôs-se em linha contra os arameus;"},
{v:10,t:"o resto do povo, confiou-o a seu irmão Abisai, que se dispôs em linha contra os amonitas."},
{v:11,t:"E Joab disse: Se os arameus forem mais fortes do que eu, virás em meu socorro; e, se os amonitas forem mais fortes do que tu, eu irei socorrer-te."},
{v:12,t:"Sê valente, e mostremo-nos fortes pelo nosso povo e pelas cidades do nosso Deus; e o Senhor faça o que lhe parecer bem.",n:"A frase de Joab resume a fé do soldado: fazer tudo o que se pode e entregar o resultado a Deus."},
{v:13,t:"Joab e o povo que estava com ele avançaram para o combate contra os arameus, que fugiram diante dele."},
{v:14,t:"Os amonitas, vendo que os arameus fugiam, fugiram também diante de Abisai e entraram na cidade. Joab deixou os amonitas e voltou a Jerusalém."},
{v:15,t:"Os arameus, vendo que tinham sido derrotados por Israel, reuniram-se todos juntos.",np:1},
{v:16,t:"Adadezer mandou buscar os arameus que estavam do outro lado do Rio, e eles vieram a Helam, tendo à frente Sobac, chefe do exército de Adadezer.",n:"O Rio, sem outro nome, é o Eufrates."},
{v:17,t:"Informaram Davi, e ele reuniu todo o Israel, atravessou o Jordão e chegou a Helam. Os arameus dispuseram-se em linha contra Davi e combateram contra ele."},
{v:18,t:"Mas os arameus fugiram diante de Israel; e Davi matou dos arameus os homens de setecentos carros e quarenta mil soldados de infantaria, e feriu Sobac, chefe do exército, que morreu ali."},
{v:19,t:"Todos os reis vassalos de Adadezer, vendo-se derrotados por Israel, fizeram a paz com Israel e ficaram-lhe sujeitos. E os arameus tiveram medo de socorrer de novo os amonitas."}
];

window.TEXTOS_SEED["2samuel"][11] = [
{s:"Davi e Betsabeia"},
{v:1,t:"Na volta do ano, no tempo em que os reis costumam sair para a guerra, Davi enviou Joab, e com ele os seus servos e todo o Israel; eles devastaram a terra dos amonitas e sitiaram Rabá. Mas Davi ficou em Jerusalém.",n:"Começa aqui a história da sucessão de Davi (capítulos 11 a 20 e 1 Reis 1 e 2), talvez escrita por uma testemunha da corte, de um realismo sem igual na literatura antiga. O narrador nota: Davi ficou. O rei que antes saía à frente do povo já não vai à guerra."},
{v:2,t:"Certa tarde, Davi levantou-se da cama e passeava pelo terraço do palácio real. Do terraço viu uma mulher que se banhava; e a mulher era muito bonita."},
{v:3,t:"Davi mandou informar-se sobre a mulher, e disseram-lhe: É Betsabeia, filha de Eliam, mulher de Urias, o heteu.",n:"Eliam e Urias são nomes que aparecem entre os valentes de Davi (23,34.39): Davi sabe que está tomando a mulher de um dos seus soldados mais fiéis."},
{v:4,t:"Davi mandou mensageiros buscá-la. Ela veio a ele, e ele se deitou com ela, que acabava de se purificar da sua impureza. Depois ela voltou para sua casa.",n:"Acabava de se purificar: depois da menstruação (Levítico 15,19-28). O detalhe mostra que a criança só podia ser de Davi."},
{v:5,t:"A mulher concebeu e mandou dizer a Davi: Estou grávida."},
{v:6,t:"Então Davi mandou dizer a Joab: Manda-me Urias, o heteu. E Joab enviou Urias a Davi.",np:1},
{v:7,t:"Quando Urias chegou, Davi perguntou-lhe como estavam Joab e o povo, e como ia a guerra."},
{v:8,t:"Depois Davi disse a Urias: Desce à tua casa e lava os pés. Urias saiu do palácio real, e foi-lhe enviado um presente da mesa do rei.",n:"Davi quer que Urias passe a noite com a mulher, para que o filho pareça dele."},
{v:9,t:"Mas Urias dormiu à porta do palácio real, com os outros servos do seu senhor, e não desceu à sua casa."},
{v:10,t:"Informaram Davi: Urias não desceu à sua casa. Davi disse a Urias: Não vens tu de viagem? Por que não desceste à tua casa?"},
{v:11,t:"Urias respondeu a Davi: A arca, Israel e Judá moram em tendas, e o meu senhor Joab e os servos do meu senhor acampam em campo aberto; e eu iria à minha casa, comer, beber e deitar-me com a minha mulher? Pela tua vida e pela vida da tua alma, não farei tal coisa!",n:"O estrangeiro, o heteu, é mais fiel à lei da guerra santa, que exigia continência dos combatentes (1 Samuel 21,6), do que o rei de Israel. A sua lealdade o condena à morte."},
{v:12,t:"Davi disse a Urias: Fica aqui ainda hoje, e amanhã te deixarei partir. E Urias ficou em Jerusalém aquele dia e o seguinte."},
{v:13,t:"Davi o convidou a comer e beber na sua presença, e o embriagou; mas à tarde Urias saiu para dormir na sua cama, com os servos do seu senhor, e não desceu à sua casa."},
{s:"A morte de Urias"},
{v:14,t:"Na manhã seguinte, Davi escreveu uma carta a Joab e a enviou por meio de Urias.",np:1},
{v:15,t:"Escreveu na carta: Ponde Urias na primeira linha, onde o combate for mais violento, e retirai-vos de junto dele, para que seja ferido e morra.",n:"Urias leva a sua própria sentença de morte. O rei que respeitou a vida do ungido Saul manda matar o seu soldado inocente."},
{v:16,t:"Joab, que sitiava a cidade, pôs Urias no lugar onde sabia que estavam os guerreiros mais valentes."},
{v:17,t:"Os homens da cidade fizeram uma saída e combateram contra Joab; caíram alguns do povo, dos servos de Davi, e morreu também Urias, o heteu."},
{v:18,t:"Joab mandou informar Davi de tudo o que se passara no combate,",np:1},
{v:19,t:"e deu esta ordem ao mensageiro: Quando acabares de contar ao rei tudo o que se passou no combate,"},
{v:20,t:"se o rei se irritar e te disser: Por que vos aproximastes tanto da cidade para combater? Não sabíeis que do alto da muralha eles atiram?"},
{v:21,t:"Quem matou Abimelec, filho de Jerobaal? Não foi uma mulher que lhe atirou do alto da muralha uma pedra de moinho, e ele morreu em Tebes? Por que vos aproximastes tanto da muralha? — então dirás: Também morreu o teu servo Urias, o heteu.",n:"Joab lembra o episódio de Juízes 9,53. Sabe que a notícia da morte de Urias acalmará a ira do rei."},
{v:22,t:"O mensageiro partiu, chegou e contou a Davi tudo o que Joab lhe mandara dizer."},
{v:23,t:"O mensageiro disse a Davi: Aqueles homens foram mais fortes do que nós e saíram contra nós em campo aberto; mas nós os repelimos até a entrada da porta."},
{v:24,t:"Então os arqueiros atiraram do alto da muralha contra os teus servos, e morreram alguns dos servos do rei; morreu também o teu servo Urias, o heteu."},
{v:25,t:"Davi disse ao mensageiro: Assim dirás a Joab: Não te aflijas com isso, porque a espada devora ora um, ora outro; intensifica o ataque contra a cidade e destrói-a. E tu, encoraja-o.",n:"A frieza da resposta mostra quanto o crime endureceu o coração de Davi."},
{v:26,t:"Quando a mulher de Urias soube que Urias, seu marido, tinha morrido, chorou por ele.",np:1},
{v:27,t:"Passado o luto, Davi mandou buscá-la e a recebeu em sua casa; ela se tornou sua mulher e lhe deu um filho. Mas o que Davi tinha feito desagradou ao Senhor.",n:"A última frase é o juízo de Deus sobre tudo o que precede: o narrador, que até aqui não comentou nada, dá a palavra ao Senhor."}
];

window.TEXTOS_SEED["2samuel"][12] = [
{s:"Natã repreende Davi"},
{v:1,t:"O Senhor enviou Natã a Davi. Natã foi ter com ele e lhe disse: Havia numa cidade dois homens, um rico e outro pobre.",n:"Natã fala por parábola: leva o rei a julgar-se a si mesmo sem o saber. É o profeta diante do poder, que o Deuteronômio punha acima do rei."},
{v:2,t:"O rico tinha ovelhas e bois em grande quantidade."},
{v:3,t:"O pobre não tinha nada, senão uma ovelhinha que tinha comprado e criado; ela crescera junto dele e dos seus filhos, comendo do seu pão, bebendo do seu copo e dormindo no seu colo: era para ele como uma filha."},
{v:4,t:"Chegou um viajante à casa do rico, e este, não querendo tomar das suas ovelhas e dos seus bois para preparar um banquete ao viajante que lhe tinha chegado, tomou a ovelha do homem pobre e preparou-a para o homem que viera à sua casa."},
{v:5,t:"Davi inflamou-se de cólera contra aquele homem e disse a Natã: Pela vida do Senhor, o homem que fez isso merece a morte!",np:1},
{v:6,t:"Pagará quatro vezes o valor da ovelha, por ter feito tal coisa e não ter tido piedade.",n:"Quatro vezes: é a restituição exigida pela Lei para o roubo de uma ovelha (Êxodo 21,37). A tradição judaica viu nesta sentença a sorte de quatro filhos de Davi: o filho de Betsabeia, Amnon, Absalão e Adonias."},
{v:7,t:"Natã disse a Davi: Esse homem és tu! Assim diz o Senhor, Deus de Israel: Eu te ungi rei sobre Israel e te livrei da mão de Saul;"},
{v:8,t:"dei-te a casa do teu senhor e pus nos teus braços as mulheres do teu senhor; dei-te a casa de Israel e de Judá; e, se isso fosse pouco, eu te daria ainda muito mais."},
{v:9,t:"Por que, então, desprezaste a palavra do Senhor, fazendo o que é mau aos seus olhos? Feriste à espada Urias, o heteu, tomaste a sua mulher para seres teu marido e o mataste com a espada dos amonitas."},
{v:10,t:"Por isso a espada não se afastará jamais da tua casa, porque me desprezaste e tomaste a mulher de Urias, o heteu, para ser tua mulher."},
{v:11,t:"Assim diz o Senhor: Farei levantar-se contra ti a desgraça da tua própria casa; tomarei as tuas mulheres diante dos teus olhos e as darei a outro, que se deitará com as tuas mulheres à luz deste sol.",n:"Cumpre-se com Absalão (16,21-22)."},
{v:12,t:"Tu o fizeste às escondidas; mas eu o farei diante de todo o Israel e diante do sol."},
{v:13,t:"Davi disse a Natã: Pequei contra o Senhor. Natã disse a Davi: O Senhor, por sua vez, perdoou o teu pecado: não morrerás.",np:1,n:"Duas palavras em hebraico, sem desculpas: pequei contra o Senhor. É a grandeza de Davi, que o distingue de Saul, sempre pronto a se justificar. O Salmo 51, o Miserere, é atribuído pelo seu título a este momento."},
{v:14,t:"Contudo, porque com isso deste aos inimigos do Senhor ocasião de blasfemar, o filho que te nasceu morrerá.",n:"Os inimigos do Senhor: o texto talvez diga, com um eufemismo dos copistas, que Davi desprezou o próprio Senhor. O perdão não suprime todas as consequências do pecado."},
{s:"A morte do menino"},
{v:15,t:"E Natã voltou para sua casa. O Senhor feriu o menino que a mulher de Urias tinha dado a Davi, e ele caiu gravemente doente.",np:1},
{v:16,t:"Davi implorou a Deus pelo menino; jejuou rigorosamente e, recolhido em casa, passava a noite deitado no chão."},
{v:17,t:"Os anciãos da sua casa insistiam junto dele para que se levantasse do chão, mas ele não quis, nem comeu com eles."},
{v:18,t:"No sétimo dia o menino morreu. Os servos de Davi tinham medo de lhe dizer que o menino estava morto, porque pensavam: Quando o menino ainda estava vivo, falávamos com ele, e ele não nos ouvia. Como lhe diremos agora: O menino morreu? Ele fará alguma loucura!"},
{v:19,t:"Mas Davi, vendo que os seus servos cochichavam entre si, compreendeu que o menino tinha morrido e perguntou aos seus servos: O menino morreu? Responderam: Morreu."},
{v:20,t:"Então Davi levantou-se do chão, lavou-se, perfumou-se e mudou de roupa; entrou na casa do Senhor e prostrou-se. Depois voltou para sua casa, pediu que lhe servissem comida e comeu."},
{v:21,t:"Os seus servos lhe disseram: Que é isto que fazes? Enquanto o menino vivia, jejuavas e choravas; e agora que o menino morreu, tu te levantas e comes!"},
{v:22,t:"Ele respondeu: Enquanto o menino vivia, jejuei e chorei, porque pensava: Quem sabe se o Senhor terá piedade de mim, e o menino viverá?"},
{v:23,t:"Mas agora que ele morreu, por que jejuaria? Poderei fazê-lo voltar? Eu irei até ele, mas ele não voltará para mim.",n:"Davi aceita a vontade de Deus com uma lucidez comovente. Eu irei até ele: à morada dos mortos, onde todos se reencontram."},
{s:"O nascimento de Salomão"},
{v:24,t:"Davi consolou Betsabeia, sua mulher; foi ter com ela e deitou-se com ela, e ela deu à luz um filho, a quem ele deu o nome de Salomão. O Senhor o amou",np:1,n:"Salomão, em hebraico Shelomo, lembra shalom, paz: nascido depois do perdão, será o rei da paz."},
{v:25,t:"e enviou o profeta Natã, que lhe deu o nome de Jedidias, isto é, Amado do Senhor, por causa do Senhor.",n:"Deus manifesta, por meio do mesmo profeta que condenou o pecado, o seu amor pelo filho de Betsabeia: é a ele que caberá a promessa de 7,12-15."},
{s:"A tomada de Rabá"},
{v:26,t:"Joab combateu contra Rabá dos amonitas e tomou a cidade real.",np:1,n:"A narrativa retoma o cerco de Rabá, deixado em 11,1: todo o drama de Davi aconteceu durante aquela guerra."},
{v:27,t:"E enviou mensageiros a Davi, para lhe dizer: Ataquei Rabá e tomei a cidade das águas.",n:"A cidade das águas era talvez o bairro baixo, junto às fontes, que abastecia a cidadela."},
{v:28,t:"Agora, pois, reúne o resto do povo, acampa contra a cidade e toma-a, para que não seja eu a tomá-la e não se dê a ela o meu nome."},
{v:29,t:"Davi reuniu todo o povo, marchou contra Rabá, atacou-a e tomou-a."},
{v:30,t:"Tirou da cabeça de Milcom a coroa, que pesava um talento de ouro e tinha uma pedra preciosíssima; e ela foi posta na cabeça de Davi. Levou também da cidade um despojo muito grande.",n:"Milcom: o deus dos amonitas, cuja estátua usava a coroa; o hebraico pode ler-se também o rei deles. Um talento pesava mais de trinta quilos: a coroa era mais para a estátua do que para um homem."},
{v:31,t:"Quanto à sua população, fê-la sair e a condenou a trabalhar nas pedreiras, com serras, picaretas e machados de ferro, e empregou-a na fabricação de tijolos; e o mesmo fez com todas as cidades dos amonitas. Depois Davi voltou com todo o exército para Jerusalém."}
];

window.TEXTOS_SEED["2samuel"][13] = [
{s:"Amnon e Tamar"},
{v:1,t:"Depois disso aconteceu o seguinte. Absalão, filho de Davi, tinha uma irmã muito bela, chamada Tamar; e Amnon, filho de Davi, apaixonou-se por ela.",n:"Começam a cumprir-se as palavras de Natã: a espada não se afastará da tua casa. O pecado de Davi repete-se nos filhos: o desejo, a violência, a morte."},
{v:2,t:"Amnon ficou tão atormentado que caiu doente por causa de Tamar, sua irmã; porque ela era virgem, e parecia-lhe impossível fazer-lhe qualquer coisa."},
{v:3,t:"Amnon tinha um amigo chamado Jonadab, filho de Samá, irmão de Davi; era um homem muito astuto."},
{v:4,t:"Ele lhe disse: Por que emagreces assim, dia após dia, tu, filho do rei? Por que não me contas? Amnon respondeu: Estou apaixonado por Tamar, irmã de meu irmão Absalão."},
{v:5,t:"Jonadab lhe disse: Deita-te na cama e finge-te doente. Quando teu pai vier visitar-te, dize-lhe: Peço-te que venha minha irmã Tamar dar-me de comer; que ela prepare a comida diante de mim, para que eu veja e coma da sua mão."},
{v:6,t:"Amnon deitou-se e fingiu-se doente. Quando o rei veio visitá-lo, Amnon disse ao rei: Peço-te que venha minha irmã Tamar e faça diante de mim dois bolinhos, e comerei da sua mão.",np:1},
{v:7,t:"Davi mandou dizer a Tamar, em casa: Vai à casa de teu irmão Amnon e prepara-lhe a comida."},
{v:8,t:"Tamar foi à casa de seu irmão Amnon, que estava deitado. Tomou farinha, amassou-a, fez os bolinhos diante dele e os cozeu."},
{v:9,t:"Depois tomou a frigideira e serviu-lhe o que tinha cozido; mas ele não quis comer. Amnon disse: Fazei sair todos daqui! E todos saíram."},
{v:10,t:"Então Amnon disse a Tamar: Traze a comida ao quarto, para que eu coma da tua mão. Tamar tomou os bolinhos que tinha feito e os levou ao quarto de seu irmão Amnon."},
{v:11,t:"Quando ela lhe apresentou a comida, ele a agarrou e disse: Vem, deita-te comigo, minha irmã."},
{v:12,t:"Ela lhe respondeu: Não, meu irmão, não me violentes! Isso não se faz em Israel; não cometas esta infâmia.",n:"Infâmia, em hebraico nebalá: a mesma palavra usada para o crime de Gabaá (Juízes 19,23) e para o de Siquém contra Dina (Gênesis 34,7)."},
{v:13,t:"E eu, para onde iria com a minha vergonha? E tu passarias por um dos infames de Israel. Fala antes ao rei, e ele não me negará a ti.",n:"A Lei proibia o casamento entre meios-irmãos (Levítico 18,9); mas Tamar, desesperada, procura uma saída, e talvez o costume ainda o tolerasse, como no caso de Abraão e Sara."},
{v:14,t:"Mas ele não quis ouvi-la; sendo mais forte do que ela, violentou-a e deitou-se com ela."},
{v:15,t:"Depois Amnon sentiu por ela um ódio imenso, maior do que o amor com que a tinha amado. E Amnon lhe disse: Levanta-te, vai-te embora!",np:1,n:"A análise do narrador é de uma verdade terrível: a paixão satisfeita pela violência converte-se em ódio."},
{v:16,t:"Ela lhe disse: Não, meu irmão! Mandar-me embora é um mal maior do que o outro que me fizeste. Mas ele não quis ouvi-la,"},
{v:17,t:"e chamou o rapaz que o servia e disse: Põe esta mulher para fora e fecha a porta atrás dela."},
{v:18,t:"Ela vestia uma túnica comprida, porque assim se vestiam as filhas virgens do rei. O servo a pôs para fora e fechou a porta atrás dela.",n:"A túnica comprida, sinal da sua condição de princesa e de virgem, é também a túnica de José (Gênesis 37,3): nas duas histórias, a veste rasgada anuncia a desgraça."},
{v:19,t:"Tamar cobriu a cabeça de cinza, rasgou a túnica comprida que vestia, pôs as mãos na cabeça e foi-se embora, gritando."},
{v:20,t:"Absalão, seu irmão, perguntou-lhe: Esteve contigo Amnon, teu irmão? Por ora, minha irmã, cala-te: ele é teu irmão. Não te aflijas com isso. E Tamar ficou desolada na casa de Absalão, seu irmão."},
{v:21,t:"Quando o rei Davi soube de tudo isso, ficou muito irritado; mas não quis contristar seu filho Amnon, porque o amava, pois era o seu primogênito.",n:"A frase sobre Amnon vem da versão grega, que a Nova Vulgata segue. Davi, que tinha pecado de modo semelhante, não tem autoridade para punir o filho; o seu silêncio abrirá caminho à vingança de Absalão."},
{v:22,t:"Absalão não falou mais com Amnon, nem para o mal nem para o bem; porque Absalão odiava Amnon por ele ter violentado Tamar, sua irmã."},
{s:"Absalão vinga Tamar"},
{v:23,t:"Dois anos depois, Absalão tinha tosquiadores em Baal-Hasor, perto de Efraim, e convidou todos os filhos do rei.",np:1},
{v:24,t:"Foi ter com o rei e disse: O teu servo tem tosquiadores. Que o rei venha, com os seus servos, à casa do teu servo."},
{v:25,t:"O rei respondeu a Absalão: Não, meu filho, não iremos todos, para não te sermos pesados. Absalão insistiu, mas ele não quis ir e deu-lhe a sua bênção."},
{v:26,t:"Absalão disse: Se não queres vir, que venha ao menos o meu irmão Amnon conosco. O rei lhe perguntou: Por que há de ir contigo?"},
{v:27,t:"Mas Absalão insistiu tanto que ele deixou ir com ele Amnon e todos os filhos do rei. E Absalão preparou um banquete de rei.",n:"O banquete de rei vem da versão grega, que a Nova Vulgata segue."},
{v:28,t:"Absalão deu esta ordem aos seus servos: Prestai atenção: quando Amnon estiver alegre com o vinho e eu vos disser: Feri Amnon!, matai-o. Não tenhais medo: sou eu quem vos dá a ordem. Sede fortes e mostrai-vos valentes."},
{v:29,t:"Os servos de Absalão fizeram com Amnon o que Absalão tinha ordenado. Então todos os filhos do rei se levantaram, montaram cada um na sua mula e fugiram.",n:"A mula era a montaria dos príncipes; Salomão será proclamado rei montado na mula de Davi (1 Reis 1,33)."},
{v:30,t:"Estavam ainda a caminho quando chegou a Davi este boato: Absalão matou todos os filhos do rei; não escapou nenhum deles!",np:1},
{v:31,t:"O rei levantou-se, rasgou as vestes e deitou-se no chão; e todos os seus servos, que estavam de pé à sua volta, rasgaram as vestes."},
{v:32,t:"Mas Jonadab, filho de Samá, irmão de Davi, tomou a palavra e disse: Que o meu senhor não pense que mataram todos os jovens, filhos do rei; só Amnon morreu, porque Absalão tinha isto decidido desde o dia em que ele violentou Tamar, sua irmã.",n:"Jonadab, que deu a Amnon o conselho fatal, conhecia também os planos de Absalão."},
{v:33,t:"Agora, pois, que o rei, meu senhor, não se aflija, pensando que todos os filhos do rei morreram: só Amnon morreu."},
{v:34,t:"Absalão tinha fugido. O jovem que estava de sentinela levantou os olhos e viu muita gente que vinha pelo caminho de Horonaim, pela encosta do monte. A sentinela veio avisar o rei, dizendo: Vejo homens que vêm pelo caminho de Horonaim."},
{v:35,t:"Jonadab disse ao rei: Aí vêm os filhos do rei! Aconteceu como disse o teu servo."},
{v:36,t:"Mal acabou de falar, chegaram os filhos do rei; entraram e levantaram a voz e choraram; e também o rei e todos os seus servos choraram amargamente."},
{v:37,t:"Absalão fugiu e foi ter com Tolmai, filho de Amiud, rei de Gessur. E Davi chorava o seu filho todos os dias.",np:1,n:"Tolmai era o avô materno de Absalão (3,3)."},
{v:38,t:"Absalão, depois de fugir para Gessur, ficou ali três anos."},
{v:39,t:"E o rei deixou de se irritar contra Absalão, porque se consolara da morte de Amnon."}
];

window.TEXTOS_SEED["2samuel"][14] = [
{s:"A mulher de Técua"},
{v:1,t:"Joab, filho de Sárvia, percebeu que o coração do rei se voltava para Absalão."},
{v:2,t:"Mandou buscar em Técua uma mulher sábia e lhe disse: Finge que estás de luto: veste roupas de luto e não te perfumes, para pareceres uma mulher que chora um morto há muito tempo.",n:"Técua, aldeia de Judá ao sul de Belém, será a terra do profeta Amós. A mulher sábia, como a de Abel-Bet-Maaca (20,16), representa a sabedoria do povo."},
{v:3,t:"Depois irás ao rei e lhe dirás estas palavras. E Joab pôs-lhe na boca as palavras que devia dizer."},
{v:4,t:"A mulher de Técua foi ter com o rei, lançou-se com o rosto por terra, prostrou-se e disse: Socorro, ó rei!",np:1},
{v:5,t:"O rei lhe perguntou: Que tens? Ela respondeu: Ai de mim, sou viúva: meu marido morreu."},
{v:6,t:"A tua serva tinha dois filhos, que brigaram no campo; não havia ninguém para separá-los, e um deles feriu o outro e o matou."},
{v:7,t:"E agora toda a família se levantou contra a tua serva, dizendo: Entrega-nos o que matou o irmão, para que o matemos em troca da vida do irmão que ele matou, e acabemos também com o herdeiro. Assim querem apagar a brasa que me resta, para não deixar ao meu marido nem nome nem descendência sobre a face da terra.",n:"A lei do vingador do sangue exigia a morte do assassino; mas, aplicada aqui, extinguiria a família. A mulher põe o rei diante do conflito entre a justiça e a misericórdia, como Natã o pusera diante da sua culpa."},
{v:8,t:"O rei disse à mulher: Vai para tua casa; eu darei ordens a teu respeito."},
{v:9,t:"A mulher de Técua disse ao rei: Ó rei, meu senhor, que a culpa caia sobre mim e sobre a casa de meu pai; que o rei e o seu trono fiquem inocentes."},
{v:10,t:"O rei disse: Se alguém te disser alguma coisa, traze-o a mim, e ele não tornará a molestar-te."},
{v:11,t:"Ela disse: Que o rei se lembre do Senhor seu Deus, para que o vingador do sangue não aumente a desgraça e não matem o meu filho. Ele respondeu: Pela vida do Senhor, não cairá por terra um só cabelo do teu filho."},
{v:12,t:"Então a mulher disse: Permite que a tua serva diga uma palavra ao rei, meu senhor. Ele respondeu: Fala.",np:1},
{v:13,t:"A mulher disse: Por que pensaste tal coisa contra o povo de Deus? Ao dizer esta palavra, o rei condena-se a si mesmo, porque não faz voltar aquele que ele baniu."},
{v:14,t:"Todos morremos; somos como a água derramada no chão, que não se pode recolher. Mas Deus não quer que uma vida se perca: ele busca meios para que o banido não fique para sempre perdido.",n:"Uma das mais belas frases do Antigo Testamento sobre a misericórdia de Deus, posta na boca de uma mulher do povo."},
{v:15,t:"Se agora vim dizer esta palavra ao rei, meu senhor, foi porque o povo me fez medo. E a tua serva pensou: Falarei ao rei; talvez o rei faça o que lhe pede a sua serva."},
{v:16,t:"O rei certamente ouvirá, para livrar a sua serva da mão de quem quer exterminar-me, a mim e a meu filho, da herança de Deus."},
{v:17,t:"A tua serva pensou: Que a palavra do rei, meu senhor, me traga tranquilidade; porque o rei, meu senhor, é como um anjo de Deus para ouvir e discernir o bem e o mal. E o Senhor teu Deus esteja contigo!"},
{v:18,t:"O rei respondeu à mulher: Não me escondas nada do que vou perguntar-te. A mulher disse: Que o rei, meu senhor, fale.",np:1},
{v:19,t:"O rei perguntou: Não está a mão de Joab contigo em tudo isto? A mulher respondeu: Pela tua vida, ó rei, meu senhor, não é possível desviar-se nem para a direita nem para a esquerda de tudo o que o rei, meu senhor, diz. Sim, foi o teu servo Joab quem me deu estas ordens e pôs na boca da tua serva todas estas palavras."},
{v:20,t:"Foi para dar outra face a este caso que o teu servo Joab fez isto. Mas o meu senhor é sábio como um anjo de Deus, para conhecer tudo o que se passa na terra."},
{s:"A volta de Absalão"},
{v:21,t:"O rei disse a Joab: Pois bem, faço o que pedes; vai e traze de volta o jovem Absalão.",np:1},
{v:22,t:"Joab lançou-se com o rosto por terra, prostrou-se e abençoou o rei. E Joab disse: Hoje o teu servo reconhece que goza do teu favor, ó rei, meu senhor, porque o rei atendeu o pedido do seu servo."},
{v:23,t:"Joab levantou-se, foi a Gessur e trouxe Absalão para Jerusalém."},
{v:24,t:"Mas o rei disse: Que ele se retire para a sua casa e não veja a minha face. E Absalão retirou-se para a sua casa e não viu a face do rei.",n:"Um perdão pela metade: Davi faz voltar o filho, mas não o recebe. A reconciliação incompleta alimentará a revolta."},
{v:25,t:"Em todo o Israel não havia homem tão elogiado pela sua beleza como Absalão: da planta dos pés ao alto da cabeça, não havia nele defeito algum.",np:1},
{v:26,t:"Quando cortava o cabelo — e cortava-o uma vez por ano, porque lhe pesava demais —, pesava o cabelo da sua cabeça: duzentos siclos, pelo peso real.",n:"Mais de dois quilos. A cabeleira, orgulho de Absalão, será a causa da sua morte (18,9)."},
{v:27,t:"Nasceram a Absalão três filhos e uma filha, chamada Tamar, que era muito bonita.",n:"Absalão deu à filha o nome da irmã violentada. Segundo 18,18, ele não tinha filho homem: talvez os filhos tenham morrido cedo."},
{v:28,t:"Absalão viveu dois anos em Jerusalém sem ver a face do rei.",np:1},
{v:29,t:"Então mandou chamar Joab, para enviá-lo ao rei; mas Joab não quis vir. Mandou chamá-lo uma segunda vez, e ele ainda não quis vir."},
{v:30,t:"Absalão disse aos seus servos: Vede: o campo de Joab está junto do meu, e ele tem ali cevada. Ide e ponde-lhe fogo. Os servos de Absalão puseram fogo à plantação. Os servos de Joab vieram com as vestes rasgadas e disseram: Os servos de Absalão puseram fogo ao campo!"},
{v:31,t:"Joab levantou-se, foi à casa de Absalão e lhe disse: Por que os teus servos puseram fogo à minha plantação?"},
{v:32,t:"Absalão respondeu a Joab: Eu te mandei chamar para te dizer: Vem cá, para que eu te envie ao rei com este recado: Para que voltei de Gessur? Melhor seria para mim ter ficado lá. Quero ver a face do rei; e, se há em mim alguma culpa, que ele me mate."},
{v:33,t:"Joab foi ter com o rei e contou-lhe tudo. O rei chamou Absalão, e ele veio ao rei e prostrou-se diante dele com o rosto em terra; e o rei beijou Absalão.",n:"O beijo do pai parece selar a reconciliação; mas Absalão já prepara a revolta."}
];

window.TEXTOS_SEED["2samuel"][15] = [
{s:"A conspiração de Absalão"},
{v:1,t:"Depois disso, Absalão arranjou para si um carro e cavalos, e cinquenta homens que corriam à sua frente.",n:"O carro e a escolta eram insígnias de rei: Absalão apresenta-se já como herdeiro. Adonias fará o mesmo (1 Reis 1,5)."},
{v:2,t:"Absalão levantava-se cedo e ficava à beira do caminho que leva à porta; e, quando alguém tinha uma causa para levar ao julgamento do rei, Absalão o chamava e perguntava: De que cidade és? Ele respondia: O teu servo é de tal tribo de Israel."},
{v:3,t:"Absalão lhe dizia: Olha, a tua causa é boa e justa, mas não há ninguém da parte do rei para te ouvir. E acrescentava:"},
{v:4,t:"Ah, se me fizessem juiz nesta terra! Todo aquele que tivesse um processo ou uma causa viria a mim, e eu lhe faria justiça!"},
{v:5,t:"E, quando alguém se aproximava para se prostrar diante dele, ele estendia a mão, o levantava e o beijava."},
{v:6,t:"Assim fazia Absalão com todos os israelitas que vinham ao rei pedir justiça; e roubava o coração dos homens de Israel.",n:"Roubava o coração: enganava-os e conquistava-os. Absalão explora o descontentamento com a justiça do rei."},
{v:7,t:"Ao fim de quatro anos, Absalão disse ao rei: Deixa-me ir a Hebron cumprir o voto que fiz ao Senhor.",np:1,n:"Quatro anos: assim a Nova Vulgata, com alguns manuscritos gregos; o hebraico diz quarenta. Hebron, onde Davi fora ungido rei, era também a cidade natal de Absalão."},
{v:8,t:"Porque o teu servo fez um voto quando morava em Gessur, na Síria: Se o Senhor me fizer voltar a Jerusalém, oferecerei um sacrifício ao Senhor."},
{v:9,t:"O rei lhe disse: Vai em paz. E ele se levantou e foi a Hebron."},
{v:10,t:"Absalão enviou emissários por todas as tribos de Israel, para dizer: Quando ouvirdes o som da trombeta, dizei: Absalão é rei em Hebron!"},
{v:11,t:"Com Absalão tinham ido de Jerusalém duzentos homens convidados, que iam de boa-fé, sem saber de nada."},
{v:12,t:"Enquanto oferecia os sacrifícios, Absalão mandou chamar da sua cidade de Gilo Aquitofel, o gilonita, conselheiro de Davi. A conspiração tornou-se poderosa, e o povo aumentava cada vez mais em torno de Absalão.",n:"Aquitofel era talvez avô de Betsabeia (11,3; 23,34): a sua traição poderia ser vingança pela desonra da neta e pela morte de Urias."},
{s:"A fuga de Davi"},
{v:13,t:"Chegou a Davi um mensageiro, que disse: O coração dos homens de Israel está com Absalão.",np:1},
{v:14,t:"Então Davi disse a todos os seus servos que estavam com ele em Jerusalém: Levantai-vos e fujamos; senão, não escaparemos de Absalão. Apressai-vos em partir, para que ele não se apresse e nos alcance, e faça cair sobre nós a desgraça, e passe a cidade ao fio da espada.",n:"Davi prefere abandonar a capital a expô-la a um cerco: não quer que Jerusalém sofra pela sua causa."},
{v:15,t:"Os servos do rei lhe disseram: Seja qual for a decisão do rei, nosso senhor, aqui estão os teus servos."},
{v:16,t:"O rei saiu, seguido de toda a sua casa; e deixou dez concubinas para guardar a casa."},
{v:17,t:"O rei saiu, e todo o povo atrás dele, e pararam na última casa da cidade."},
{v:18,t:"Todos os seus servos passavam ao seu lado; e todos os cereteus e feleteus, e todos os geteus, seiscentos homens que o tinham seguido desde Gat, desfilavam diante do rei."},
{v:19,t:"O rei disse a Etai, o geteu: Por que vens tu também conosco? Volta e fica com o rei, porque és estrangeiro e exilado da tua terra.",np:1,n:"Volta e fica com o rei: com Absalão, que será rei. Davi deixa o estrangeiro livre de uma causa que não é sua."},
{v:20,t:"Chegaste ontem, e hoje te faria andar errante conosco, quando eu mesmo vou sem saber para onde? Volta e leva contigo os teus irmãos; e que o Senhor use contigo de bondade e fidelidade."},
{v:21,t:"Etai respondeu ao rei: Pela vida do Senhor e pela vida do rei, meu senhor: onde estiver o rei, meu senhor, para a morte ou para a vida, lá estará o teu servo.",n:"A fidelidade do estrangeiro lembra a de Rute, a moabita, bisavó de Davi (Rute 1,16-17)."},
{v:22,t:"Davi disse a Etai: Então vem e passa. E Etai, o geteu, passou com todos os seus homens e todas as crianças que estavam com ele."},
{v:23,t:"Toda a terra chorava em alta voz, enquanto todo o povo passava. O rei atravessou a torrente do Cedron, e todo o povo seguia em direção ao deserto.",n:"Mil anos depois, Jesus, traído por um amigo como Davi por Aquitofel, atravessará a mesma torrente do Cedron para ir ao monte das Oliveiras (João 18,1)."},
{v:24,t:"Veio também Sadoc, e com ele todos os levitas, carregando a arca da aliança de Deus; depuseram a arca de Deus, e Abiatar ofereceu sacrifícios até que todo o povo acabasse de sair da cidade.",np:1},
{v:25,t:"O rei disse a Sadoc: Leva a arca de Deus de volta para a cidade. Se eu achar graça aos olhos do Senhor, ele me fará voltar e me deixará vê-la, a ela e à sua morada.",n:"Davi não faz da arca um amuleto, como os israelitas no tempo de Heli (1 Samuel 4). Entrega-se à vontade de Deus."},
{v:26,t:"Mas, se ele disser: Não me agradas, aqui estou: que ele faça de mim o que lhe parecer bem."},
{v:27,t:"O rei disse ainda ao sacerdote Sadoc: Vês? Volta em paz para a cidade, com os vossos dois filhos, Aquimaás, teu filho, e Jônatas, filho de Abiatar."},
{v:28,t:"Eu esperarei nos vaus do deserto, até que me chegue de vós alguma notícia."},
{v:29,t:"Sadoc e Abiatar levaram de volta a Jerusalém a arca de Deus e ficaram lá."},
{s:"Davi no monte das Oliveiras"},
{v:30,t:"Davi subia a encosta do monte das Oliveiras; subia chorando, com a cabeça coberta e descalço; e todo o povo que estava com ele cobria a cabeça e subia chorando.",np:1},
{v:31,t:"Informaram Davi de que também Aquitofel estava entre os conjurados com Absalão, e Davi disse: Senhor, peço-te, torna insensato o conselho de Aquitofel!"},
{v:32,t:"Quando Davi chegou ao cume do monte, onde se adorava a Deus, veio ao seu encontro Cusai, o araquita, com a túnica rasgada e a cabeça coberta de terra.",n:"A oração de Davi é atendida no mesmo instante: Cusai será o instrumento de Deus contra Aquitofel."},
{v:33,t:"Davi lhe disse: Se vieres comigo, serás um peso para mim;"},
{v:34,t:"mas, se voltares para a cidade e disseres a Absalão: Ó rei, serei teu servo; antes fui servo de teu pai, agora serei teu servo, então frustrarás em meu favor o conselho de Aquitofel."},
{v:35,t:"Terás lá contigo os sacerdotes Sadoc e Abiatar; tudo o que ouvires do palácio do rei, contarás aos sacerdotes Sadoc e Abiatar."},
{v:36,t:"Estão lá com eles os seus dois filhos, Aquimaás, filho de Sadoc, e Jônatas, filho de Abiatar: por meio deles me fareis saber tudo o que ouvirdes."},
{v:37,t:"Cusai, o amigo de Davi, chegou à cidade no momento em que Absalão entrava em Jerusalém.",n:"Amigo do rei era um título da corte: o conselheiro íntimo."}
];

window.TEXTOS_SEED["2samuel"][16] = [
{s:"Davi e Siba"},
{v:1,t:"Davi tinha passado um pouco além do cume do monte, quando Siba, servo de Meribaal, veio ao seu encontro com dois jumentos selados, carregados de duzentos pães, cem cachos de passas, cem frutas de verão e um odre de vinho."},
{v:2,t:"O rei perguntou a Siba: Que queres fazer com isso? Siba respondeu: Os jumentos são para a família do rei montar; os pães e as frutas de verão, para os teus servos comerem; e o vinho, para beber quem desfalecer no deserto."},
{v:3,t:"O rei perguntou: Onde está o filho do teu senhor? Siba respondeu ao rei: Ficou em Jerusalém, porque disse: Hoje a casa de Israel me devolverá o reino de meu pai.",n:"Siba calunia o seu senhor para ficar com os seus bens; Meribaal dará a sua versão em 19,25-31."},
{v:4,t:"O rei disse a Siba: Pois bem, tudo o que era de Meribaal é teu. Siba disse: Prostro-me diante de ti! Que eu ache graça aos teus olhos, ó rei, meu senhor!"},
{s:"Semei amaldiçoa Davi"},
{v:5,t:"Quando o rei Davi chegou a Baurim, saiu de lá um homem da família da casa de Saul, chamado Semei, filho de Gera; vinha saindo e amaldiçoando,",np:1},
{v:6,t:"e atirava pedras contra Davi e contra todos os servos do rei Davi, embora todo o povo e todos os valentes estivessem à direita e à esquerda do rei."},
{v:7,t:"Semei dizia assim, amaldiçoando: Vai-te, vai-te, homem sanguinário, homem perverso!"},
{v:8,t:"O Senhor fez recair sobre ti todo o sangue da casa de Saul, cujo reino usurpaste; e o Senhor entregou o reino nas mãos de Absalão, teu filho. Aí estás na desgraça, porque és um homem sanguinário!",n:"Para os partidários de Saul, Davi tinha subido ao trono sobre os cadáveres de Abner, de Isbaal e, talvez, dos descendentes de Saul entregues aos gabaonitas (capítulo 21)."},
{v:9,t:"Abisai, filho de Sárvia, disse ao rei: Por que este cão morto amaldiçoa o rei, meu senhor? Deixa-me ir cortar-lhe a cabeça.",np:1},
{v:10,t:"Mas o rei disse: Que tenho eu convosco, filhos de Sárvia? Se ele amaldiçoa, e se o Senhor lhe disse: Amaldiçoa Davi, quem poderá dizer-lhe: Por que fazes isso?"},
{v:11,t:"E o rei disse a Abisai e a todos os seus servos: Vede: o meu filho, que saiu das minhas entranhas, procura tirar-me a vida; quanto mais este benjaminita! Deixai-o amaldiçoar, porque foi o Senhor que lhe mandou."},
{v:12,t:"Talvez o Senhor olhe para a minha aflição e me pague com bens esta maldição de hoje.",n:"Davi aceita a humilhação como vinda de Deus, e espera dele a reviravolta. A atitude é a do justo perseguido dos Salmos."},
{v:13,t:"Davi e os seus homens seguiam pelo caminho, e Semei ia pela encosta do monte, ao lado dele, amaldiçoando, atirando pedras e levantando poeira contra ele."},
{v:14,t:"O rei e todo o povo que estava com ele chegaram cansados junto às águas, e ali descansaram."},
{s:"Absalão em Jerusalém"},
{v:15,t:"Absalão e todo o povo, os homens de Israel, entraram em Jerusalém, e Aquitofel com ele.",np:1},
{v:16,t:"Quando Cusai, o araquita, amigo de Davi, chegou junto de Absalão, disse-lhe: Viva o rei! Viva o rei!",n:"Cusai não diz qual rei: a sua aclamação é ambígua, como a sua lealdade."},
{v:17,t:"Absalão lhe disse: É esta a tua lealdade para com o teu amigo? Por que não foste com o teu amigo?"},
{v:18,t:"Cusai respondeu a Absalão: Não! Aquele que o Senhor, este povo e todos os homens de Israel escolheram, dele serei, e com ele ficarei."},
{v:19,t:"Além disso, a quem vou servir? Não é ao filho do rei? Como servi a teu pai, assim te servirei."},
{v:20,t:"Absalão disse a Aquitofel: Aconselhai-vos: que devemos fazer?",np:1},
{v:21,t:"Aquitofel respondeu a Absalão: Une-te às concubinas de teu pai, que ele deixou para guardar a casa; e, quando todo o Israel souber que ultrajaste teu pai, as mãos de todos os que estão contigo se fortalecerão.",n:"Tomar o harém do rei era proclamar-se seu sucessor e tornar a ruptura irreparável: os partidários de Absalão já não teriam como voltar atrás."},
{v:22,t:"Armaram então para Absalão uma tenda no terraço, e Absalão uniu-se às concubinas de seu pai à vista de todo o Israel.",n:"No mesmo terraço de onde Davi vira Betsabeia (11,2): cumpre-se à letra a palavra de Natã (12,11-12)."},
{v:23,t:"O conselho que Aquitofel dava naqueles dias era tido como se alguém consultasse a palavra de Deus: assim era todo conselho de Aquitofel, tanto para Davi como para Absalão."}
];

window.TEXTOS_SEED["2samuel"][17] = [
{s:"Os conselhos de Aquitofel e de Cusai"},
{v:1,t:"Aquitofel disse a Absalão: Deixa-me escolher doze mil homens e partir esta noite em perseguição de Davi."},
{v:2,t:"Cairei sobre ele enquanto está cansado e desanimado, e o aterrorizarei; e, quando todo o povo que está com ele fugir, matarei só o rei, que ficará sozinho,"},
{v:3,t:"e trarei todo o povo de volta a ti, como a noiva volta para o seu marido. Tu só procuras a vida de um homem, e todo o povo ficará em paz.",n:"O plano é militarmente perfeito: rápido, e limitado a uma só vítima. Por isso Cusai precisa desacreditá-lo."},
{v:4,t:"A proposta agradou a Absalão e a todos os anciãos de Israel."},
{v:5,t:"Mas Absalão disse: Chamai também Cusai, o araquita, e ouçamos também o que ele diz.",np:1},
{v:6,t:"Quando Cusai chegou junto de Absalão, Absalão lhe disse: Aquitofel falou assim. Devemos fazer o que ele diz, ou não? Fala tu."},
{v:7,t:"Cusai respondeu a Absalão: Desta vez o conselho que Aquitofel deu não é bom."},
{v:8,t:"E Cusai acrescentou: Tu conheces teu pai e os seus homens: são muito valentes e estão exasperados como uma ursa no campo à qual roubaram os filhotes. Além disso, teu pai é homem de guerra, e não passará a noite com o povo;"},
{v:9,t:"certamente está agora escondido em alguma cova, ou em outro lugar. E, se logo no começo cair algum dos teus, quem o souber dirá: Houve uma derrota entre o povo que segue Absalão!"},
{v:10,t:"Então até o mais valente, que tem coração de leão, perderá o ânimo; porque todo o Israel sabe que teu pai é um herói, e que são valentes todos os que estão com ele."},
{v:11,t:"Eis, pois, o que me parece o conselho acertado: que se reúna junto de ti todo o Israel, desde Dã até Bersabeia, numeroso como a areia do mar, e que tu mesmo marches ao combate.",n:"Cusai lisonjeia a vaidade de Absalão: ele à frente de todo o Israel. E ganha o tempo de que Davi precisa."},
{v:12,t:"Cairemos sobre ele em qualquer lugar onde se encontrar, e o cobriremos como o orvalho cobre a terra; e não deixaremos com vida nem ele nem nenhum dos homens que estão com ele."},
{v:13,t:"E, se ele se retirar para alguma cidade, todo o Israel levará cordas até aquela cidade, e a arrastaremos para o vale, até que não se encontre dela nem uma pedrinha."},
{v:14,t:"Absalão e todos os homens de Israel disseram: O conselho de Cusai, o araquita, é melhor do que o de Aquitofel. O Senhor tinha decidido frustrar o bom conselho de Aquitofel, para fazer cair a desgraça sobre Absalão.",n:"É o centro teológico da narrativa: na trama das intrigas humanas, é Deus quem conduz a história, respondendo à oração de Davi (15,31)."},
{s:"Davi atravessa o Jordão"},
{v:15,t:"Cusai disse aos sacerdotes Sadoc e Abiatar: Aquitofel aconselhou isto e isto a Absalão e aos anciãos de Israel, e eu aconselhei isto e isto.",np:1},
{v:16,t:"Agora, pois, mandai depressa avisar Davi: Não passes esta noite nos vaus do deserto, mas atravessa sem demora, para que o rei e todo o povo que está com ele não sejam aniquilados."},
{v:17,t:"Jônatas e Aquimaás esperavam junto à fonte de Rogel; uma criada ia avisá-los, e eles iam levar a notícia ao rei Davi, porque não podiam ser vistos entrando na cidade.",n:"A fonte de Rogel ficava no vale do Cedron, ao sul da cidade. A criada que ia buscar água não despertava suspeitas."},
{v:18,t:"Mas um rapaz os viu e avisou Absalão. Os dois partiram depressa e entraram na casa de um homem de Baurim, que tinha um poço no pátio; e desceram ao poço."},
{v:19,t:"A mulher tomou uma coberta, estendeu-a sobre a boca do poço e espalhou grãos por cima, e nada se percebeu.",n:"Como Raabe em Jericó (Josué 2,6), uma mulher esconde os mensageiros e salva a causa de Israel."},
{v:20,t:"Quando os servos de Absalão chegaram à casa da mulher, perguntaram: Onde estão Aquimaás e Jônatas? A mulher respondeu: Passaram por aqui, em direção à água. Eles procuraram e, não os encontrando, voltaram a Jerusalém."},
{v:21,t:"Depois que eles se foram, os dois saíram do poço e foram avisar o rei Davi, dizendo-lhe: Levantai-vos e atravessai depressa o rio, porque Aquitofel deu tal conselho contra vós."},
{v:22,t:"Davi levantou-se com todo o povo que estava com ele, e atravessaram o Jordão; ao romper do dia, não havia ninguém que não tivesse atravessado o rio."},
{v:23,t:"Aquitofel, vendo que o seu conselho não tinha sido seguido, selou o jumento, partiu e foi para casa, na sua cidade; pôs em ordem a sua casa e enforcou-se. Morreu e foi sepultado no túmulo de seu pai.",np:1,n:"Aquitofel prevê a derrota de Absalão e o castigo que o espera. O conselheiro traidor que se enforca prefigura, para os Padres da Igreja, Judas, o traidor de Jesus (Mateus 27,5)."},
{s:"Davi em Maanaim"},
{v:24,t:"Davi chegou a Maanaim, e Absalão atravessou o Jordão com todos os homens de Israel.",np:1,n:"Maanaim, a antiga capital de Isbaal, acolhe agora Davi fugitivo."},
{v:25,t:"Absalão tinha posto Amasa à frente do exército, no lugar de Joab. Amasa era filho de um homem chamado Jeter, o ismaelita, que se unira a Abigail, filha de Jessé, irmã de Sárvia, mãe de Joab.",n:"Ismaelita: assim a Nova Vulgata, com 1 Crônicas 2,17; o hebraico diz israelita. Amasa era sobrinho de Davi e primo de Joab: a guerra é uma guerra de família."},
{v:26,t:"E Israel acampou com Absalão na terra de Galaad."},
{v:27,t:"Quando Davi chegou a Maanaim, Sobi, filho de Naás, de Rabá dos amonitas, Maquir, filho de Amiel, de Lodabar, e Berzelai, o galaadita, de Rogelim,",np:1,n:"Três homens de além do Jordão socorrem Davi: um amonita, filho do antigo inimigo; Maquir, que tinha acolhido Meribaal; e o velho Berzelai. Os amigos de Davi aparecem na hora da desgraça."},
{v:28,t:"trouxeram camas, tapetes, bacias e vasilhas de barro, trigo, cevada, farinha, grão-de-bico torrado, favas e lentilhas,"},
{v:29,t:"mel, manteiga, ovelhas e bezerros cevados, e deram tudo isso a Davi e ao povo que estava com ele, para comerem; porque pensavam: O povo está esfomeado, cansado e sedento no deserto."}
];

window.TEXTOS_SEED["2samuel"][18] = [
{s:"A batalha no bosque de Efraim"},
{v:1,t:"Davi passou em revista o povo que estava com ele e pôs à sua frente chefes de mil e chefes de cem."},
{v:2,t:"Davi dividiu o povo em três partes: um terço sob o comando de Joab, um terço sob o comando de Abisai, filho de Sárvia, irmão de Joab, e um terço sob o comando de Etai, de Gat. E o rei disse ao povo: Eu também sairei convosco."},
{v:3,t:"Mas o povo respondeu: Não sairás. Se fugirmos, não farão caso de nós; e, se metade de nós morrer, não se importarão; mas tu vales por dez mil de nós. É melhor, pois, que nos socorras da cidade."},
{v:4,t:"O rei lhes disse: Farei o que vos parecer bem. E o rei ficou de pé junto à porta, enquanto todo o povo saía em grupos de cem e de mil."},
{v:5,t:"O rei deu esta ordem a Joab, a Abisai e a Etai: Tratai com brandura, por amor de mim, o jovem Absalão. E todo o povo ouviu a ordem que o rei deu a todos os chefes a respeito de Absalão.",n:"O pai prevalece sobre o rei: Davi pede a vida do filho que quer tirar-lhe o trono e a vida."},
{v:6,t:"O povo saiu a campo contra Israel, e a batalha travou-se no bosque de Efraim.",np:1,n:"O bosque de Efraim ficava na Transjordânia, perto de Maanaim, e não no território da tribo de Efraim."},
{v:7,t:"Ali o povo de Israel foi derrotado pelos servos de Davi, e houve naquele dia uma grande matança: vinte mil homens."},
{v:8,t:"O combate espalhou-se por toda aquela região, e naquele dia o bosque devorou mais gente do que a espada."},
{s:"A morte de Absalão"},
{v:9,t:"Absalão deu de frente com os servos de Davi. Ia montado numa mula; e, quando a mula passou por baixo dos ramos espessos de um grande carvalho, a cabeça de Absalão ficou presa no carvalho, e ele ficou suspenso entre o céu e a terra, enquanto a mula que ele montava seguia adiante.",np:1,n:"A tradição imaginou que Absalão ficou preso pela longa cabeleira de que se orgulhava (14,26). A mula, montaria real, foge debaixo dele: o reino lhe escapa."},
{v:10,t:"Um homem viu isso e avisou Joab, dizendo: Vi Absalão pendurado num carvalho."},
{v:11,t:"Joab disse ao homem que lhe dava a notícia: Se o viste, por que não o abateste ali mesmo? Eu te teria dado dez siclos de prata e um cinturão."},
{v:12,t:"O homem respondeu a Joab: Ainda que me pesasses nas mãos mil siclos de prata, eu não levantaria a mão contra o filho do rei; porque nós ouvimos o rei dar esta ordem a ti, a Abisai e a Etai: Poupai, seja quem for, o jovem Absalão!"},
{v:13,t:"E, se eu tivesse agido traiçoeiramente, arriscando a minha vida, nada disso ficaria escondido do rei, e tu mesmo te porias contra mim."},
{v:14,t:"Joab disse: Não vou perder tempo contigo. Tomou três dardos na mão e cravou-os no coração de Absalão, que ainda estava vivo, preso no carvalho;",n:"Joab desobedece ao rei, como tantas vezes, por razão de Estado: enquanto Absalão vivesse, a guerra continuaria."},
{v:15,t:"e dez jovens, escudeiros de Joab, cercaram Absalão, feriram-no e acabaram de matá-lo."},
{v:16,t:"Joab tocou a trombeta, e o povo deixou de perseguir Israel, porque Joab o deteve."},
{v:17,t:"Tomaram Absalão, lançaram-no numa grande cova no bosque e ergueram sobre ele um enorme monte de pedras. E todo o Israel fugiu, cada um para a sua tenda.",n:"O monte de pedras sobre o cadáver era a sepultura dos malditos, como a de Acã (Josué 7,26) e a do rei de Hai."},
{v:18,t:"Absalão, ainda em vida, tinha erguido para si uma coluna, que está no vale do Rei, porque dizia: Não tenho filho que conserve a memória do meu nome. Deu à coluna o seu próprio nome, e ela se chama até hoje Monumento de Absalão.",n:"À letra, Mão de Absalão: a mão designava o monumento. O chamado túmulo de Absalão, no vale do Cedron, é muito posterior. O contraste é amargo: o homem que se ergueu um monumento jaz debaixo de um monte de pedras."},
{s:"Davi recebe a notícia"},
{v:19,t:"Aquimaás, filho de Sadoc, disse: Deixa-me correr e anunciar ao rei a boa notícia de que o Senhor lhe fez justiça contra os seus inimigos.",np:1},
{v:20,t:"Joab lhe disse: Hoje não és tu o portador de boas notícias; tu as levarás outro dia, mas hoje não levarás boas notícias, porque o filho do rei morreu."},
{v:21,t:"E Joab disse ao etíope: Vai contar ao rei o que viste. O etíope prostrou-se diante de Joab e partiu correndo.",n:"Joab escolhe um estrangeiro, um escravo talvez, para levar a notícia perigosa; lembra-se do amalecita que anunciou a morte de Saul (1,15)."},
{v:22,t:"Aquimaás, filho de Sadoc, insistiu com Joab: Aconteça o que acontecer, deixa-me correr também atrás do etíope! Joab respondeu: Para que queres correr, meu filho? Não receberás recompensa por essa notícia."},
{v:23,t:"Aconteça o que acontecer, correrei! Joab lhe disse: Corre! E Aquimaás, correndo pelo caminho do vale, passou à frente do etíope."},
{v:24,t:"Davi estava sentado entre as duas portas. A sentinela, que tinha subido ao terraço da porta, sobre a muralha, levantou os olhos e viu um homem que corria sozinho,",np:1},
{v:25,t:"e gritou para avisar o rei. O rei disse: Se está sozinho, traz boas notícias na boca. Enquanto ele vinha se aproximando,"},
{v:26,t:"a sentinela viu outro homem correndo e gritou ao porteiro: Aí vem outro homem correndo sozinho! O rei disse: Esse também traz boas notícias."},
{v:27,t:"A sentinela disse: Pelo modo de correr, o primeiro parece Aquimaás, filho de Sadoc. O rei disse: É um homem de bem; vem trazer boas notícias."},
{v:28,t:"Aquimaás gritou ao rei: Paz! E, prostrando-se com o rosto em terra diante do rei, disse: Bendito seja o Senhor teu Deus, que entregou os homens que levantaram a mão contra o rei, meu senhor!"},
{v:29,t:"O rei perguntou: Vai bem o jovem Absalão? Aquimaás respondeu: Vi um grande tumulto quando Joab enviou o servo do rei e a mim, teu servo; mas não sei o que era.",n:"Aquimaás sabe, mas não tem coragem de dizer."},
{v:30,t:"O rei lhe disse: Afasta-te e fica ali. Ele se afastou e ficou esperando."},
{v:31,t:"Então chegou o etíope e disse: Boas notícias para o rei, meu senhor! Hoje o Senhor te fez justiça, livrando-te da mão de todos os que se levantaram contra ti."},
{v:32,t:"O rei perguntou ao etíope: Vai bem o jovem Absalão? O etíope respondeu: Que tenham a sorte desse jovem os inimigos do rei, meu senhor, e todos os que se levantam contra ti para te fazer mal!"}
];

window.TEXTOS_SEED["2samuel"][19] = [
{s:"O luto de Davi"},
{v:1,t:"Então o rei estremeceu, subiu ao quarto que ficava sobre a porta e chorou; e, enquanto subia, dizia: Meu filho Absalão! Meu filho, meu filho Absalão! Quem me dera ter morrido em teu lugar! Absalão, meu filho, meu filho!",n:"O grito de um pai, talvez o mais comovente do Antigo Testamento. Davi chora o filho, e chora também, sem dizê-lo, o próprio pecado, do qual nasceu toda esta desgraça."},
{v:2,t:"Avisaram Joab: O rei está chorando e se lamentando por Absalão.",np:1},
{v:3,t:"E naquele dia a vitória transformou-se em luto para todo o povo, porque o povo ouviu dizer naquele dia: O rei está aflito por causa do seu filho."},
{v:4,t:"Naquele dia o povo entrou às escondidas na cidade, como entra envergonhado um exército que fugiu do combate."},
{v:5,t:"O rei tinha coberto o rosto e gritava em alta voz: Meu filho Absalão! Absalão, meu filho, meu filho!"},
{v:6,t:"Joab entrou em casa, onde estava o rei, e disse: Hoje cobriste de vergonha o rosto de todos os teus servos, que hoje salvaram a tua vida, a vida dos teus filhos e das tuas filhas, a vida das tuas mulheres e das tuas concubinas.",np:1},
{v:7,t:"Amas os que te odeiam e odeias os que te amam. Mostraste hoje que não te importas com os chefes nem com os servos; agora sei que, se Absalão estivesse vivo e nós todos mortos, estarias contente."},
{v:8,t:"Agora, pois, levanta-te, sai e fala ao coração dos teus servos. Juro-te pelo Senhor que, se não saíres, nem um só homem ficará contigo esta noite; e isso será para ti pior do que todos os males que te aconteceram desde a tua juventude até agora.",n:"Joab é duro, mas tem razão: o rei não pode deixar-se vencer pela dor do pai."},
{v:9,t:"O rei levantou-se e sentou-se à porta; e anunciaram a todo o povo: O rei está sentado à porta. E todo o povo veio à presença do rei. Os homens de Israel, porém, tinham fugido, cada um para a sua tenda."},
{s:"A volta do rei"},
{v:10,t:"Em todas as tribos de Israel, o povo discutia, dizendo: O rei nos livrou da mão dos nossos inimigos, ele nos salvou da mão dos filisteus; e agora fugiu do país por causa de Absalão.",np:1},
{v:11,t:"Mas Absalão, que tínhamos ungido rei sobre nós, morreu na guerra. Por que ficais calados e não trazeis o rei de volta?"},
{v:12,t:"O que se dizia em todo o Israel chegou ao rei, em sua casa. Então o rei Davi mandou dizer aos sacerdotes Sadoc e Abiatar: Falai aos anciãos de Judá e dizei-lhes: Por que sereis os últimos a trazer o rei de volta para a sua casa?"},
{v:13,t:"Vós sois meus irmãos, sois meus ossos e minha carne: por que sereis os últimos a trazer de volta o rei?",n:"Judá, a tribo de Davi, tinha apoiado Absalão em Hebron. Davi a atrai com o laço de sangue, e as outras tribos se sentirão preteridas (19,42-44)."},
{v:14,t:"E dizei a Amasa: Não és tu meus ossos e minha carne? Que Deus me faça isto e mais aquilo, se não fores para sempre o chefe do meu exército em lugar de Joab!",n:"Davi nomeia chefe do exército o general do filho rebelde: gesto de reconciliação com Judá, e castigo para Joab, que matou Absalão."},
{v:15,t:"Assim ele inclinou o coração de todos os homens de Judá, como se fossem um só homem; e eles mandaram dizer ao rei: Volta, tu e todos os teus servos."},
{v:16,t:"O rei voltou e chegou ao Jordão; e Judá veio a Guilgal, ao encontro do rei, para fazê-lo atravessar o Jordão."},
{s:"Semei, Meribaal e Berzelai"},
{v:17,t:"Semei, filho de Gera, benjaminita, de Baurim, apressou-se a descer com os homens de Judá ao encontro do rei Davi,",np:1},
{v:18,t:"acompanhado de mil homens de Benjamim; e também Siba, o servo da casa de Saul, com os seus quinze filhos e os seus vinte servos. Tinham-se lançado ao Jordão adiante do rei"},
{v:19,t:"e atravessado o vau, para fazer passar a família do rei e fazer o que lhe agradasse. Semei, filho de Gera, prostrou-se diante do rei, quando este ia atravessar o Jordão,"},
{v:20,t:"e disse-lhe: Que o meu senhor não me leve em conta a culpa e não se lembre da ofensa que o teu servo cometeu no dia em que o rei, meu senhor, saiu de Jerusalém; que o rei não a guarde no coração."},
{v:21,t:"O teu servo reconhece o seu pecado; por isso vim hoje, o primeiro de toda a casa de José, descer ao encontro do rei, meu senhor.",n:"A casa de José: as tribos do Norte, cujas principais eram Efraim e Manassés, filhos de José. Semei vem à frente de mil benjaminitas: a sua submissão tem peso político."},
{v:22,t:"Abisai, filho de Sárvia, tomou a palavra e disse: Não há de morrer Semei, por ter amaldiçoado o ungido do Senhor?"},
{v:23,t:"Mas Davi disse: Que tenho eu convosco, filhos de Sárvia, para que hoje vos façais meus adversários? Há de alguém morrer hoje em Israel? Não sei eu que hoje voltei a ser rei sobre Israel?",n:"Adversários, em hebraico satã: o que se opõe. O dia da volta do rei é dia de anistia. Mas Davi, no leito de morte, recomendará a Salomão que não deixe Semei impune (1 Reis 2,8-9)."},
{v:24,t:"E o rei disse a Semei: Não morrerás! E o rei jurou-lhe."},
{v:25,t:"Meribaal, filho de Saul, também desceu ao encontro do rei. Não tinha cuidado dos pés, nem cortado as unhas, nem aparado a barba, nem lavado a roupa, desde o dia em que o rei partira até o dia em que voltou em paz.",np:1,n:"Filho de Saul: isto é, neto. O abandono do corpo e da roupa era sinal de luto: Meribaal esteve de luto todo o tempo do exílio do rei."},
{v:26,t:"Quando veio de Jerusalém ao encontro do rei, o rei lhe perguntou: Por que não foste comigo, Meribaal?"},
{v:27,t:"Ele respondeu: Ó rei, meu senhor, o meu servo me enganou! Eu, teu servo, tinha-lhe dito: Vou mandar selar o jumento, para montar e ir com o rei; porque o teu servo é coxo."},
{v:28,t:"E ainda caluniou o teu servo diante do rei, meu senhor. Mas o rei, meu senhor, é como um anjo de Deus: faze o que te parecer bem."},
{v:29,t:"Toda a casa de meu pai não merecia senão a morte diante do rei, meu senhor; e tu puseste o teu servo entre os que comem à tua mesa. Que direito tenho eu ainda de clamar ao rei?"},
{v:30,t:"O rei lhe disse: Para que falar mais? Eu decido: tu e Siba repartireis as terras.",n:"Davi não sabe em quem acreditar e divide as terras, como Salomão quererá dividir a criança (1 Reis 3,25). A resposta de Meribaal, no versículo seguinte, revela quem dizia a verdade."},
{v:31,t:"Meribaal respondeu ao rei: Que ele fique até com tudo, já que o rei, meu senhor, voltou em paz para a sua casa!"},
{v:32,t:"Berzelai, o galaadita, tinha descido de Rogelim e acompanhou o rei na travessia do Jordão, para se despedir dele junto ao Jordão.",np:1},
{v:33,t:"Berzelai era muito velho: tinha oitenta anos. Ele tinha sustentado o rei durante a sua permanência em Maanaim, porque era homem muito rico."},
{v:34,t:"O rei disse a Berzelai: Vem comigo, e eu te sustentarei junto de mim em Jerusalém."},
{v:35,t:"Mas Berzelai respondeu ao rei: Quantos anos de vida me restam, para que eu suba com o rei a Jerusalém?"},
{v:36,t:"Tenho hoje oitenta anos. Posso ainda distinguir o que é bom do que é mau? Pode o teu servo saborear o que come e o que bebe? Posso ainda ouvir a voz dos cantores e das cantoras? Por que o teu servo haveria de ser ainda um peso para o rei, meu senhor?",n:"O retrato da velhice, com a sua serenidade e a sua lucidez, lembra o do Eclesiastes (Eclesiastes 12,1-7)."},
{v:37,t:"O teu servo acompanhará o rei só um pouco além do Jordão. Por que me daria o rei tal recompensa?"},
{v:38,t:"Deixa, peço-te, o teu servo voltar, para morrer na minha cidade, junto ao túmulo de meu pai e de minha mãe. Mas aqui está o teu servo Camaã: que ele vá com o rei, meu senhor; faze por ele o que te parecer bem.",n:"Camaã era talvez filho de Berzelai. Davi recomendará a Salomão os filhos de Berzelai (1 Reis 2,7)."},
{v:39,t:"O rei disse: Camaã passará comigo, e farei por ele o que te agradar; e tudo o que me pedires, eu te concederei."},
{v:40,t:"Todo o povo atravessou o Jordão, e o rei também. O rei beijou Berzelai e o abençoou, e ele voltou para a sua terra."},
{s:"A discórdia entre Judá e Israel"},
{v:41,t:"O rei passou a Guilgal, e Camaã com ele. Todo o povo de Judá e metade do povo de Israel tinham acompanhado o rei na travessia.",np:1},
{v:42,t:"Então todos os homens de Israel vieram ao rei e lhe disseram: Por que os nossos irmãos, os homens de Judá, te roubaram, e fizeram atravessar o Jordão o rei, a sua família e todos os homens de Davi com ele?"},
{v:43,t:"Todos os homens de Judá responderam aos homens de Israel: Porque o rei é nosso parente. Por que vos irritais por isso? Acaso comemos à custa do rei, ou recebemos algum presente?"},
{v:44,t:"Os homens de Israel responderam aos homens de Judá: Temos dez partes no rei, e também em Davi temos mais direito do que vós. Por que nos desprezastes? Não fomos nós os primeiros a falar em trazer de volta o nosso rei? Mas as palavras dos homens de Judá foram mais duras que as dos homens de Israel.",n:"Dez partes: as dez tribos do Norte. A rivalidade entre Judá e Israel, que Davi não soube apaziguar, levará à divisão do reino depois de Salomão (1 Reis 12)."}
];

window.TEXTOS_SEED["2samuel"][20] = [
{s:"A revolta de Seba"},
{v:1,l:["Encontrava-se ali um homem perverso, chamado Seba, filho de Bocri, benjaminita. Ele tocou a trombeta e disse:","Não temos parte com Davi,","nem herança com o filho de Jessé!","Homens de Israel, cada um para as suas tendas!"],n:"O mesmo grito de guerra ressoará na divisão do reino, contra Roboão, neto de Davi (1 Reis 12,16)."},
{v:2,t:"Todos os homens de Israel abandonaram Davi e seguiram Seba, filho de Bocri; mas os homens de Judá acompanharam o seu rei desde o Jordão até Jerusalém."},
{v:3,t:"Quando o rei chegou à sua casa, em Jerusalém, tomou as dez concubinas que tinha deixado para guardar a casa e as pôs sob guarda, provendo-lhes o sustento; mas não se uniu mais a elas. Ficaram encerradas até o dia da sua morte, vivendo como viúvas.",np:1,n:"Depois de possuídas por Absalão (16,22), não podiam voltar ao rei."},
{s:"Joab mata Amasa"},
{v:4,t:"O rei disse a Amasa: Convoca-me os homens de Judá dentro de três dias, e apresenta-te aqui.",np:1},
{v:5,t:"Amasa partiu para convocar Judá, mas demorou-se além do prazo que o rei lhe tinha fixado."},
{v:6,t:"Então Davi disse a Abisai: Agora Seba, filho de Bocri, nos fará mais mal do que Absalão. Toma os servos do teu senhor e persegue-o, para que ele não encontre cidades fortificadas e nos escape."},
{v:7,t:"Saíram atrás dele os homens de Joab, os cereteus, os feleteus e todos os valentes; saíram de Jerusalém em perseguição de Seba, filho de Bocri."},
{v:8,t:"Quando estavam junto da grande pedra que há em Gabaon, Amasa veio ao seu encontro. Joab vestia a sua roupa de guerra, e trazia à cintura, sobre os rins, uma espada escondida, que, com um leve movimento, lhe caiu da bainha na mão."},
{v:9,t:"Joab disse a Amasa: Vais bem, meu irmão? E com a mão direita pegou a barba de Amasa, como para beijá-lo."},
{v:10,t:"Amasa não reparou na espada que Joab tinha na mão; e Joab o feriu no ventre e derramou-lhe as entranhas por terra, sem precisar de segundo golpe; e ele morreu. Depois Joab e seu irmão Abisai seguiram em perseguição de Seba, filho de Bocri.",n:"Joab elimina o rival como eliminara Abner (3,27), com a mesma traição. Retoma assim, sem ordem do rei, o comando do exército."},
{v:11,t:"Um dos rapazes de Joab ficou junto ao cadáver de Amasa e dizia: Quem estiver com Joab e for por Davi, siga Joab!"},
{v:12,t:"Amasa jazia banhado em sangue no meio do caminho. Aquele homem, vendo que todo o povo parava para olhar, tirou Amasa do caminho para o campo e cobriu-o com uma capa, porque via que todos os que passavam paravam junto dele."},
{v:13,t:"Tirado ele do caminho, todos os homens passaram, seguindo Joab em perseguição de Seba, filho de Bocri."},
{s:"A mulher sábia de Abel"},
{v:14,t:"Seba percorreu todas as tribos de Israel até Abel-Bet-Maaca; e todos os bocritas se reuniram e entraram também atrás dele na cidade.",np:1,n:"Abel-Bet-Maaca ficava no extremo norte do país, perto de Dã. Os bocritas eram talvez o clã de Seba."},
{v:15,t:"Os homens de Joab vieram cercá-lo em Abel-Bet-Maaca; levantaram contra a cidade uma rampa, que chegava até o antemuro, e todo o povo que estava com Joab procurava derrubar a muralha."},
{v:16,t:"Então uma mulher sábia gritou do alto da cidade: Ouvi, ouvi! Dizei a Joab: Aproxima-te daqui, para que eu te fale."},
{v:17,t:"Quando ele se aproximou, a mulher lhe perguntou: És tu Joab? Ele respondeu: Sou eu. Ela lhe disse: Ouve as palavras da tua serva. Ele respondeu: Estou ouvindo."},
{v:18,t:"Ela disse: Antigamente costumava-se dizer: Consulte-se em Abel, e assim se resolve a questão.",n:"Abel era famosa pela sabedoria dos seus conselheiros: ali se ia pedir o parecer que encerrava as disputas."},
{v:19,t:"Eu sou das cidades pacíficas e fiéis de Israel, e tu procuras destruir uma cidade que é mãe em Israel. Por que queres devorar a herança do Senhor?",n:"Uma cidade que é mãe: uma metrópole, com as aldeias que dela dependem, as suas filhas."},
{v:20,t:"Joab respondeu: Longe, longe de mim devorar ou destruir!"},
{v:21,t:"Não se trata disso. Um homem da montanha de Efraim, chamado Seba, filho de Bocri, levantou a mão contra o rei Davi. Entregai-o só a ele, e me retirarei da cidade. A mulher disse a Joab: A cabeça dele te será atirada por cima da muralha."},
{v:22,t:"A mulher foi falar com todo o povo, com sabedoria; e eles cortaram a cabeça de Seba, filho de Bocri, e a atiraram a Joab. Ele tocou a trombeta, e retiraram-se da cidade, cada um para a sua tenda. E Joab voltou a Jerusalém, para junto do rei."},
{s:"Os oficiais de Davi"},
{v:23,t:"Joab comandava todo o exército de Israel; Banaías, filho de Joiada, comandava os cereteus e os feleteus;",np:1,n:"Segunda lista dos oficiais de Davi (ver 8,16-18). Aparece agora o encarregado dos trabalhos forçados: o reino se organiza como os reinos vizinhos, como Samuel tinha anunciado (1 Samuel 8,11-17)."},
{v:24,t:"Adoniram era o encarregado dos trabalhos forçados; Josafá, filho de Ailud, era o arauto;"},
{v:25,t:"Siva era o escriba; Sadoc e Abiatar eram sacerdotes;"},
{v:26,t:"e Ira, o jairita, era também sacerdote de Davi."}
];
